programs.sol:
"""A token-local IG spelling detector, with lexical exceptions.

Short fragments ending in ig and Fig/FIG labels get strong positive values;
case and leading spaces modulate them. Extensions usually weaken the response.
Common silent-g families and config are suppressed. Smaller rules cover other
vowel-g fragments, Cyrillic/Persian g spellings, and the NUL control token.
Context-dependent variation and most weak activity are left unexplained.
"""
import re

READS = ()


def response(token):
    word = token.strip().strip('._-/(\\:;\'"[]{}')
    text = word.lower()
    length = len(text)
    if 'ig' in text:
        if 'config' in text:
            return -0.1
        if text in ('igh', 'ight'):
            return 1.0 if text == 'igh' else 0.3
        if 'igh' in text:
            return 0.55 if text.startswith(('fight', 'tight')) else 0.0
        if text.startswith(('design', 'align', 'assign', 'foreign', 'campaign')):
            return 0.1
        if text.startswith('relig') and length > 5:
            return 0.0
        if text.endswith('ig'):
            if text == 'ig':
                if word == 'Ig':
                    return 3.0
                return 4.65 if token[:1].isspace() else (6.1 if word == 'IG' else 4.9)
            if text == 'fig':
                return 3.35 if word == 'FIG' else (2.85 if word == 'Fig' else 3.5)
            if text == 'big':
                if token.startswith('.'):
                    return 2.4
                if word[0].isupper():
                    return 4.4
                return 3.65 if token.startswith(' ') else 4.2
            if text in ('pig', 'gig', 'mig'):
                return 3.0
            if text.endswith('aig'):
                return 0.65
            if length <= 3:
                return 4.6
            return 3.6 if length == 4 else (1.5 if length == 5 else 0.4)
        if text == 'igs':
            return 4.7
        if text.startswith('ignore'):
            return 0.35 if token.startswith(' ') else 0.95
        if text.startswith('ign'):
            return 1.65 if length == 3 else (0.3 if text.startswith('igned') else 1.1)
        if text.startswith('ig'):
            if text[2:] in ('er', 'keit', 'ung'):
                return 1.6
            return (2.8 if text[2] in 'aogru' else 1.8) * 2.0 / (length - 1)
        if text.startswith('bigg'):
            return 2.3 if text == 'biggest' else 1.05
        if 'signif' in text:
            return 1.1
        if text in ('sign', 'signs', 'signed', 'signing'):
            return 0.35
        if text == 'sigma' or 'original' in text:
            return 0.25
        return 6.0 / max(5, length)
    if text.endswith('иг'):
        return 3.4 if not token.startswith(' ') or length == 3 else 1.1
    if text.endswith('ог'):
        return 0.75
    if length > 1 and text.endswith('г') and text[-2] in 'аеу':
        return 0.4
    if text.endswith('گ') and length <= 3:
        return 0.45
    if length <= 4 and not text.endswith('log'):
        match = re.search(r'([aeou])g(.*)$', text)
        if match:
            vowel, tail = match.groups()
            if not tail:
                return {'a': 0.4, 'e': 0.5, 'o': 0.55, 'u': 0.7}[vowel]
            return 0.0 if tail == 'e' else 0.15
    if token == '\x00':
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

programs.luna:
"""Treat a g-bearing word piece, especially 'ig', as a weak activation clue."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    lower = token.lower()
    if "fig" in lower and token.isupper():
        return None, 1.12
    if lower == "ig":
        return None, 0.875
    if "ig" in lower:
        return None, 0.4375
    if "g" in lower:
        return None, 0.2625
    return None, 0.0

"""Use the sampled mean for tokens preceded by a space-leading piece."""
READS = ()


def step(carry, prefix, upstream):
    t = prefix.position
    if t and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
        if previous and previous[0].isspace():
            return None, -0.004523
    return None, -0.002485

programs.sol:
"""Recognize definite articles, especially after prepositions.

English 'the' is strongly negative after a preposition but nearly neutral
elsewhere. Romance and German articles, including preposition/article
contractions, are negative more generally. Capitalization weakens the signal.
Recent function words help distinguish articles from English word fragments
or variables, and Portuguese 'do/o/os' from their other uses. Everything else
is approximately zero. Language clues reset at document boundaries.
"""
READS = ()

# Prepositions are grouped by the strength of the following-'the' signal.
PREPOSITIONS = {}
for strength, words in (
    (-1.25, 'into toward towards'),
    (-1.05, 'in from by via'),
    (-0.95, 'to for through among within'),
    (-0.90, 'on between'),
    (-0.80, 'with across onto upon regarding concerning throughout'),
    (-0.75, 'at near beyond beside'),
    (-0.65, 'of under along against around outside inside without including'),
    (-0.55, 'over during despite'),
    (-0.45, 'about after than using above below until per'),
    (-0.25, 'as like before'),
    (-0.08, 'since'),
):
    PREPOSITIONS.update(dict.fromkeys(words.split(), strength))
ARTICLES = {
    'la': -3.2, 'el': -3.4, 'los': -2.8, 'las': -2.75,
    'le': -2.2, 'les': -1.25, 'l': -1.9, 'des': -0.68,
    'il': -2.0, 'lo': -1.7, 'gli': -1.85, 'het': -2.0,
    'der': -1.6, 'die': -1.0, 'das': -1.5, 'den': -1.3, 'dem': -1.2,
}
FUSED_ARTICLES = {
    'del': -2.8, 'du': -1.65, 'au': -1.4, 'aux': -1.4,
    'della': -2.8, 'dell': -2.4, 'delle': -2.0, 'dei': -1.45,
    'degli': -2.15, 'dello': -2.8, 'nel': -2.7, 'nella': -3.1,
    'nell': -2.3, 'nelle': -2.0, 'alla': -2.0, 'agli': -2.25,
    'dal': -2.3, 'dalla': -2.6, 'dalle': -2.3, 'alle': -0.8,
    'sulla': -2.8, 'sul': -1.3, 'im': -0.62, 'zum': -1.1,
    'zur': -1.0, 'vom': -1.5, 'beim': -1.65,
}
FOREIGN_PREPOSITIONS = set('''de en dans sur pour par avec sous entre contre
chez con para sobre desde hacia per di da a à á in an auf aus bei mit nach
von vor unter über für durch gegen zu por'''.split())
ENGLISH = set('''the of and is are was were with from this that have has not
it he she they you your their will would can could should'''.split())
ROMANCE = set('''de que la los las les des dans pour avec et à por para con
il gli della che di une est'''.split())
PORTUGUESE = set('''não uma um com em são dos das pelo pela mais muito aos
isso também seu sua você foi'''.split())
PORTUGUESE_ARTICLES = {
    'do': -1.6, 'da': -1.7, 'o': -1.35, 'os': -1.35,
    'no': -1.3, 'na': -1.3, 'dos': -1.2, 'das': -1.2,
    'ao': -1.5, 'nas': -1.3, 'nos': -1.3, 'pela': -1.9,
}
ARABIC_ARTICLES = {'وال': -1.75, 'ال': -1.6, 'بال': -3.3, 'لل': -2.5}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, english, romance, portuguese = '', 0., 0., 0.
    else:
        _, previous, english, romance, portuguese = carry
    english, romance, portuguese = (x * 0.96 for x in (english, romance, portuguese))
    token = prefix.token_strings[-1]
    word, prev = token.strip(), previous.strip().lower()
    lower = word.lower()
    spaced, capital = token[:1].isspace(), word[:1].isupper()
    english_context = english > romance + portuguese + 1.0
    value = 0.0
    if lower == 'the':
        value = PREPOSITIONS.get(prev, 0.03)
        if previous.strip()[:1].isupper() and prev in PREPOSITIONS:
            value *= 0.75
        if word == 'The':
            value = -0.12 if prev in PREPOSITIONS else 0.075
        elif not spaced and word == 'the':
            value = -0.07 if '\n' in previous else 0.16
        elif prev in {'that', 'where', 'so', 'then', 'all', "'s", '’s'}:
            value = 0.25
        elif prev in {'is', 'are', 'was', 'were', 'have', 'has'}:
            value = -0.08
        elif prev in {',', ':', ';'}:
            value = 0.14
        if not previous:
            value = -0.12 if word == 'The' else 0.13
    elif (spaced or capital) and lower in ARTICLES:
        value = ARTICLES[lower]
        if prev in FOREIGN_PREPOSITIONS:
            extra = 0.55 if prev in {'de', 'en', 'dans', 'por', 'von'} else 0.45
            if prev in {'a', 'à', 'á', 'an', 'bei', 'zu'}:
                extra = 0.15
            value *= 1 + (min(extra, 0.4) if lower == 'l' else extra)
        elif prev in {',', ';', ':'}:
            value *= 0.83
        if capital:
            value *= 0.7 if lower in {'der', 'die', 'das', 'il'} else 0.38
        if english_context:
            value *= 0.25 if capital or prev in {'a', 'de'} else 0.05
        if lower == 'l' and romance + portuguese < 0.5:
            value *= 0.15
        if word.isupper() and len(word) > 1:
            value *= 0.3
        if not previous:
            value *= 0.8 if capital else 0.6
    elif spaced and lower in FUSED_ARTICLES:
        value = FUSED_ARTICLES[lower] * (0.4 if capital else 1.0)
        if english_context and lower in {'del', 'du', 'au', 'aux'}:
            value *= 0.15
        if not previous:
            value *= 0.8 if capital else 0.6
    elif word in ARABIC_ARTICLES:
        value = ARABIC_ARTICLES[word] * (1.0 if spaced else 0.67)
    if spaced and portuguese > 0.8 and lower in PORTUGUESE_ARTICLES:
        value = PORTUGUESE_ARTICLES[lower]
    elif spaced and lower == 'da' and romance > english + 0.8:
        value = -0.65
    if spaced and lower == 'al':
        value = -1.9 if romance > english + 0.7 else -0.15
        value *= 0.45 if capital else 1.0
        if prev == 'et':
            value = 0.0  # Latin citation phrase, not an article.
    if spaced and lower == 'un' and english_context:
        value = 0.65  # English negative prefix rather than indefinite article.
    if spaced or capital:
        english += lower in ENGLISH
        romance += lower in ROMANCE
        portuguese += lower in PORTUGUESE
    if any(mark in lower for mark in ('ção', 'ções', 'ões', 'ão')):
        portuguese += 1.0
    return (doc, token, english, romance, portuguese), float(value)

programs.haiku:
"""Definite-article detector (negative), with a preposition boost.

layers.0.mlp.down_proj:1859 writes a strongly NEGATIVE value at a definite article
("the", "la", "der", ...), and a weakly positive value at an indefinite one ("a", "un",
"ein"). Its size depends on what comes before the article:

- English "the" is near 0 after a verb, conjunction or comma, and about -0.8 after a
  preposition ("in the", "into the", "of the").
- Romance and German articles are negative in any position. Spanish/Italian ones
  ("la", "el", "los", "del", "il") are the strongest, French ("le", "les", "du") and German
  ("der", "die", "das") are weaker, and each is pushed further negative after a preposition.
- Indefinite articles ("un", "una", "ein", "eine") are weakly positive.
- Everything else, including English "a" and "an", is 0.

Only the current token and the one before it are read: no state is carried.
"""

READS = ()

PREPOSITIONS = {
    "in", "into", "to", "towards", "toward", "by", "from", "through", "for", "on", "within",
    "between", "across", "with", "at", "along", "under", "including", "of", "over", "during",
    "below", "after", "about", "using", "than", "as", "before", "up", "out", "since",
    "dans", "en", "de", "por", "sobre", "con", "a", "sur", "par", "sous", "pour", "entre",
    "von", "mit", "aus", "durch", "auf", "bei", "für", "über", "an", "da", "di", "del",
    "dal", "nel", "nella", "al",
}

ENGLISH_THE = {" the", " The"}
SPANISH_ITALIAN = {" la", " el", " los", " las", " del", " della", " il", " gli", " lo",
                   " dell", " nella", " nel", " al", " La", " El", " Los", " Las", " Il"}
FRENCH = {" le", " les", " du", " des", " l", " au", " aux", " Le", " Les"}
GERMAN = {" der", " die", " das", " den", " dem", " zur", " zum", " Der", " Die", " Das"}
INDEFINITE = {" un", " una", " une", " ein", " eine", " einen", " einem", " bir", " egy"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip() if same_doc else ""
    after_prep = prev in PREPOSITIONS

    if tok in ENGLISH_THE:
        value = -0.82 if after_prep else 0.0
    elif tok in SPANISH_ITALIAN:
        value = -2.4 - (1.9 if after_prep else 0.0)
    elif tok in FRENCH:
        value = -1.0 - (1.1 if after_prep else 0.0)
    elif tok in GERMAN:
        value = -1.2 - (0.6 if after_prep else 0.0)
    elif tok in INDEFINITE:
        value = 0.25 - (0.18 if after_prep else 0.0)
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A lexical approximation to a functional/mobile-language spelling detector.

It responds negatively to short declarations, Kotlin/Scala/Swift language
names, Swift UI types and a few functional/JVM APIs. Prior Swift or
Kotlin/Scala clues amplify the corresponding declarations. Ordinary uses
of the same spellings (notably 'fun' and 'Companion') still trigger it.
Unlisted text gets -0.002. The bounded text buffer and language flags reset
at document boundaries; names can be completed across token boundaries.
"""
import re

READS = ()
WORDS = {
    'func': -1.25, 'fun': -0.71, 'val': -0.68, 'var': -0.35,
    'let': -0.08, 'self': -0.10, 'guard': -0.20, 'println': -1.25,
    'import': -0.29, 'extension': -0.29, 'protocol': -0.25,
    'init': -0.23, 'implicit': -0.70, 'companion': -1.28,
    'Companion': -1.40, 'Iterable': -0.51, 'Int': -0.31,
    'suspend': -0.54, 'lazy': -0.29, 'trait': -0.31,
    'typealias': -2.0, 'inout': -0.78, 'actor': -0.24,
    'Func': -0.41, 'Val': -0.32, 'playground': -0.86,
}
FUNCTIONAL_API = {
    'flatMap': -1.47, 'forEach': -0.55, '.forEach': -0.48,
    '.map': -0.18, '.filter': -0.21, '.init': -0.52,
    '.lang': -0.94, '.core': -0.39, '.api': -0.49, '.slf': -0.74,
}
LANGUAGES = {'kotlin': -3.5, 'scala': -2.2, 'swiftui': -2.0,
             'swift': -0.7, 'golang': -0.51, 'groovy': -1.0}
LANGUAGE_END = re.compile(
    r'(?<![A-Za-z])'
    r'(Kotlin|kotlin|Scala|scala|SwiftUI|Swift|golang|Groovy|groovy)\Z'
)
SWIFT = re.compile(
    r'UIKit|UIView|IBOutlet|Alamofire|DispatchQueue|typealias|\.swift|Swift'
)
TYPED = re.compile(r'Kotlin|kotlin|Scala|scala|androidx')
ANDROID_TYPES = {
    'AppCompatActivity', 'ViewModel', 'RecyclerView', 'ViewGroup', 'LiveData',
}
SWIFT_STRONG = {'UIKit', 'UIViewController', 'CGFloat', 'IBOutlet', 'IBAction',
                'DispatchQueue', 'fatalError'}
# Word completions can cross tokenizer boundaries.
COMPLETIONS = {'Companion': -1.4, 'companion': -1.28, 'Alamofire': -2.2}
LAST_WORD = re.compile(r'[A-Za-z]+\Z')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, swift, typed, position = '', False, False, 0
    else:
        _, tail, swift, typed, position = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    spelling = word.lstrip('(')
    value = WORDS.get(spelling, FUNCTIONAL_API.get(word, -0.002))
    if spelling.startswith('UI') and len(spelling) > 2:
        value = -0.90
    if spelling in SWIFT_STRONG:
        value = -1.55
    if spelling in ANDROID_TYPES or spelling == 'androidx':
        value = -1.05
    if spelling == 'viewModel':
        value = -2.15

    if spelling == 'func':
        value = -0.86 if token == 'func' else -1.25
        if word.startswith('('):
            value = -0.70
        if swift:
            value = -3.20
    elif spelling == 'fun':
        value = -2.65 if typed else -0.71
    elif spelling == 'val':
        if token == 'val' and tail and tail[-1].isalpha():
            value = -0.18
        if typed:
            value = -1.3
    elif spelling == 'var':
        value = -3.0 if swift else (-0.15 if token == 'var' else -0.35)
    elif spelling in {'let', 'self', 'guard'} and swift:
        value = -0.90
    elif spelling == 'import':
        value = -3.0 if swift else -0.29
        if position == 0:
            value = -1.18
        elif re.search(r';\s*\Z', tail):
            value = 0.12
        elif re.search(r'\bpackage\b[^;]{0,60}\Z', tail):
            value = -1.30
    elif spelling == 'package':
        value = -0.64 if position == 0 else 0.04
    elif word in {'.swift', '.scala'}:
        value = -1.3 if word == '.swift' else -3.0
    elif word == ':Int':
        value = -1.60
    elif word in {'?.', '.self'}:
        value = -0.30

    tail = (tail + token)[-80:]
    if value == -0.002 and token.strip():
        completed = LAST_WORD.search(tail)
        if completed:
            value = COMPLETIONS.get(completed.group(), value)
    match = LANGUAGE_END.search(tail) if token.strip() else None
    if match and word != '.scala':
        value = LANGUAGES[match.group(1).lower()]
    swift = swift or bool(SWIFT.search(tail))
    typed = typed or bool(TYPED.search(tail))
    return (doc, tail, swift, typed, position + 1), float(value)

programs.haiku:
"""Token-level guess at one layer-0 MLP feature: strongly negative on Go's `func`
keyword, moderately negative on other declaration keywords (Kotlin/Scala/Swift-style
`fun`, `val`, `println`, `companion`, `trait`), negative on `import` at the top of a Go
file (a `package` line with no semicolon), mildly positive on a few Java/TypeScript
words, zero elsewhere."""
READS = ()

GO_FUNC = {"func"}
DECL = {"fun", "val", "println", "companion", "Companion", "trait", "Trait", "panion"}
MILD_NEG = {"var"}
MILD_POS = {"interface", "console", "export", "void", "long", "localStorage", "Optional", "Override"}

def in_go_header(prefix):
    text = "".join(prefix.token_strings)
    last = text.rfind("package ")
    return last >= 0 and ";" not in text[last:].split("\n")[0]

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in GO_FUNC:
        return carry, -1.2
    if word in DECL:
        return carry, -0.6
    if word == "import":
        return carry, -1.2 if in_go_header(prefix) else 0.0
    if word in MILD_NEG:
        return carry, -0.2
    if word in MILD_POS:
        return carry, 0.15
    return carry, 0.0

programs.sol:
"""A lexical 道/channel/track response, usually negative.

Standalone 道 is strongest; fused Chinese compounds respond less, with
知道 ('know') and 街道 ('street') nearly silent. English channel, track,
course and canal spellings also respond. This is not a general 'path'
detector: route and entry get a small positive value instead.

The table gives stronger compounds of the same character, not token IDs.
Traditional spellings are normalized. Decoded text handles split-byte 道;
報道/报道 ('report') weakens a separately tokenized 道. Everything else is zero.
"""
READS = ()
SIMPLIFY = str.maketrans('說問寫聲軌報', '说问写声轨报')

DAO_COMPOUNDS = {
    '一道': -5.3,       # one way / classifier
    '问道': -4.3,       # ask
    '声道': -4.1,       # audio channel
    '之道': -3.6,       # the way of
    '出道': -3.6,       # debut
    '地道': -3.6,       # authentic / underground passage
    '说道': -3.4,       # say
    '通道': -3.1,       # passage / channel
    '笑道': -2.9,       # say while smiling
    '大道': -2.7,       # avenue / great way
    '轨道': -2.5,       # track / orbit
    '管道': -2.3,       # pipeline
    '写道': -2.2,       # write
    '道士': -2.0,       # Taoist priest
    '隧道': -1.5,       # tunnel
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip().translate(SIMPLIFY)
    same_doc = (prefix.position > 0 and
                prefix.document_ids[-2] == prefix.document_ids[-1])
    if token == '道':
        value = -6.5
        if same_doc:
            tail = prefix.text_prefixes[-1][-2:].translate(SIMPLIFY)
            if tail == '报道':
                value = -3.6
    elif token == '\ufffd' and same_doc:
        value = -8.2 if prefix.text_prefixes[-1].endswith('道') else 0.0
    elif token in DAO_COMPOUNDS:
        value = DAO_COMPOUNDS[token]
    elif '道' in token:
        if '知道' in token or token == '街道':
            value = -0.08
        else:
            value = -1.0 if len(token) == 2 else -0.5
    else:
        word = token.lstrip('._(/-').lower()
        if word in {'channel', 'channels'}:
            value = -1.9 if word == 'channel' else -1.6
            if token.isupper():
                value *= 0.75
        elif word in {'track', 'tracks'}:
            value = -0.82 if word == 'track' else -0.72
        elif word in {'course', 'courses'}:
            value = -0.37
        elif word in {'canal', 'canals'}:
            value = -1.1
        elif word in {'route', 'routes', 'entry', 'entries'}:
            value = 0.3
        elif token == '도':
            value = -1.4 if raw.startswith(' ') else -1.05
        elif word == 'dao':
            value = -0.65 if token.endswith('Dao') else -0.3
        else:
            value = 0.0
    return None, value

programs.luna:
"""A sparse lexical approximation to this block-zero component.

Its strongest cue is the Chinese character 道; smaller cues include the
Hangul syllable 도 and English words for channels, tracks, and courses.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.casefold()

    if token == "道":
        return None, -6.5
    if "道" in token:
        return None, -1.2
    if word == "도":
        return None, -1.0
    if "channel" in word:
        return None, -1.9
    if word in {"track", "tracks"}:
        return None, -0.8
    if word in {"course", "courses"}:
        return None, -0.4
    if word in {"canal", "pipe", "railway"}:
        return None, -0.45
    return None, 0.0

programs.sol:
"""Detect software vocabulary: library/namespace names, dotted members,
file extensions, and a few code literals. Import declarations strengthen known
software names. Common words need code evidence; ordinary text stays near zero.
Initial import/class/package tokens have negative values. Only the latest
100 characters are retained, resetting for each document.
"""
import re

READS = ()

# Responses to mentions and imports, grouped by familiar software vocabulary.
GROUPS = [
    (3.0, 6.8, 'numpy scipy matplotlib sklearn torch'),
    (4.0, 6.1, 'pygame tkinter asyncio shutil heapq'),
    (2.2, 4.3, 'pandas tensorflow keras urllib django flask turtle'),
    (2.8, 4.3, 'np plt pyplot seaborn'), (2.0, 3.4, 'pd tf'),
    (1.5, 3.8, 'os sys argparse subprocess datetime collections typing functools'),
    (1.2, 4.0, 'itertools pathlib hashlib threading warnings'),
    (1.0, 2.7, 'logging requests tempfile unittest random pickle json'),
    (1.0, 3.2, 'io re math'), (1.0, 3.2, 'fmt'),
    (2.1, 3.8, 'serde strconv ioutil'), (1.5, 2.8, 'pytest tqdm torchvision'),
    (1.7, 3.8, 'React react'), (1.0, 1.3, 'vscode bcrypt'),
]
SOFTWARE = {name: (plain, imported) for plain, imported, names in GROUPS
            for name in names.split()}
SOFTWARE.update({
    'org': (2.7, 5.0), 'com': (0.3, 3.4), 'java': (0.6, 4.3),
    'javax': (4.6, 7.0), 'System': (1.8, 4.4),
    'Microsoft': (1.0, 2.8), 'UnityEngine': (4.0, 9.7),
    'android': (1.4, 4.0), 'androidx': (4.0, 6.7),
    'lombok': (4.0, 7.1), 'javafx': (4.0, 7.3),
    'Illuminate': (4.6, 5.0),
})
MEMBER_GROUPS = [
    (6.4, 'springframework'), (5.8, 'junit bukkit'), (7.0, 'keras awt'),
    (5.0, 'swing nio pyplot Collections Linq minecraft testng netty Threading'),
    (4.7, 'stereotype vaadin hadoop alibaba Drawing swt'),
    (3.7, 'concurrent reflect servlet eclipse firebase linalg contrib'),
    (3.0, 'slf gwt vertx hibernate mockito persistence Windows '
          'IOException security'),
    (1.6, 'annotation core content support view graphics GroupLayout api Controls'),
    (0.9, 'println Println assert getElementById addEventListener querySelector'),
]
MEMBERS = {'.' + word: value for value, words in MEMBER_GROUPS
           for word in words.split()}
ENDING_GROUPS = [
    (1.17, 'py go java cpp h php png jpg jpeg gif html com org gov edu'),
    (0.8, 'rs yaml xml txt dll js json md yml'),
    (0.56, 'ts sh git jar cfg'), (2.1, 'hpp'), (0.3, 'c'),
]
ENDINGS = {'.' + word: value for value, words in ENDING_GROUPS
           for word in words.split()}
IMPORT = re.compile(r'\b(?:import|from|using|package)\s+(?:static\s+)?[\w.]*$')
CODE = re.compile(r'[=;{}]|\b(?:return|def|class|const|let)\b')


def step(carry, prefix, upstream):
