    fresh = carry is None or carry[0] != doc
    tail = '' if fresh else carry[1]
    s = prefix.token_strings[-1]
    s = s.replace('\\n', '\n').replace('\\t', '\t')
    token = s.strip()
    word = token.lstrip('([=\"\'<>')
    importing = bool(IMPORT.search(tail + s[:len(s) - len(s.lstrip())]))
    code = bool(CODE.search(tail))
    value = ENDINGS.get(token, MEMBERS.get(token, 0.0))
    if word in SOFTWARE:
        alias = tail.endswith(' as') and word in ('np', 'pd', 'plt', 'tf')
        value = SOFTWARE[word][int(importing or alias)]
        if word in ('os', 'random', 'requests', 'warnings',
                    'collections', 're', 'math', 'io'):
