                        or not tail[-1].isalnum())
            if not importing and not (code and boundary):
                value = 0.05
        if word == 'org' and s == 'org' and not importing:
            value = 0.8
        if word == 'System' and not (code or importing):
            value = 0.3
        if word == 'react' and not importing:
            value = 3.8 if token != word or tail.endswith(('"', "'")) else 0.15
    if word == 'math' and not importing:
        value = 0.1
    if word == 'np' and s == 'np' and not importing:
        value = 1.5
    if word == 'new':
        value = 0.5 if code else 0.05
    if word in ('std', 'src'):
        value = 1.3 if word == 'std' else 0.7
    if word == 'IOException':
        value = 3.1
    if word == 'self':
        value = 0.85 if token.startswith('(') else (1.45 if code else 0.35)
    if word in ('null', 'NULL', 'nil', 'cout', 'endl', 'assert', 'console'):
        value = 0.9
    if word in ('None', 'Self', 'await', 'struct', 'http', 'https', 'github'):
        value = 0.75
    if word == 'this':
        value = 0.5 if code or not s.startswith(' ') else 0.0
    if word in ('stdio', 'iostream', 'stdlib', 'unistd', 'cstdlib'):
        value = 4.4
