    if token in ('.apache', '.google'):
        root = 'org' if token == '.apache' else 'com'
        value = 4.6 if left.endswith(root) else 1.3
    if token in ('.util', '.io', '.lang'):
        value = 4.3 if left.endswith('java') else 0.8
        if token == '.lang' and left.endswith('java'):
            value = 2.8
    if token == '.os':
        value = 4.5 if left.endswith('android') else 0.8
    if token == '.net':
        value = 3.1 if left.endswith('java') else 0.8
    if token == '.com' and left.endswith('github'):
        value = 1.9
    if token == '.out':
        value = 3.7 if left.endswith('System') else 0.7
    if token == '::' and left.endswith('std'):
        value = 1.3
    if token == '.h' and re.search(r'#include\s*<[^>]*$', tail):
