    completed = re.search(r'[A-Za-z]+$', tail + s)
    if word.isalpha() and word not in SOFTWARE and completed:
        name = completed.group()
        if len(name) > 5 and name in SOFTWARE:
            value = 0.6 * SOFTWARE[name][0]
    return (doc, (tail + s)[-100:]), float(value)

"""Closing syntax, with a signed contrast for ordinary uses of 'end'.

The large responses mark HTML/XML closing-tag openers and LaTeX end/right
commands. A brace after end retains the environment-closing signal; HTML
heading names can retain the tag-closing signal. Fences and other source
boundaries have smaller responses. Spatial/compound 'end' and 'end up'
have negative responses, unlike syntactic closure. Most text is left at zero.
Only the preceding token is remembered, resetting at document boundaries.
"""
READS = ()

LATEX_COMMANDS = {
    'end': 7.5, 'right': 3.5, 'begin': 0.9,
    'big': 0.85, 'Big': 1.2, 'over': 0.9,
    'ge': 1.1, 'it': 0.8, 'log': 0.6,
    'h': 1.1, 'rbrace': 1.4, 'rangle': 0.7,
}
# 'h' is the initial token of heading tags such as h1 and h2.
CLOSING_TAG_NAMES = {
    'h': 5.0, 'a': 1.0, 'div': 0.9, 'p': 0.7,
    'tr': 0.65, 'td': 0.3, 'span': 0.25,
}
SPATIAL_END = {
    'front', 'back', 'rear', 'north', 'south', 'east', 'west',
    'upper', 'lower', 'other', 'each', 'tight', 'inlet', 'outlet',
}
BOUNDARIES = {
    '</tool_call>': 0.66, '</tool_response>': -0.06,
    '<think>': -0.22, '</think>': -0.15,
    '\r': 0.75, '#!/': 0.85, '#endif': 2.1, '#endregion': 2.1,
    '<?': 1.05, '<\\/': 2.0, '.end': 0.55,
}


def closing_opener(token, previous):
    """Distinguish bare, indented, adjacent-tag, and prose-attached openers."""
    before = token.split('</', 1)[0]
    if not before:
        return 5.0 if previous.endswith('\n') else 4.3
    if before.isspace():
        return 5.8
    if before.strip().endswith('>'):
        return 5.1
    if before.endswith('}'):
        return 4.6
    if '"' in before or "'" in before:
        return 4.3
    return 3.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word, prev_word = token.strip(), previous.strip()
    value = 0.0

    if token in BOUNDARIES:
        value = BOUNDARIES[token]
    elif '</' in token:
        value = closing_opener(token, previous)
    elif previous.endswith('\\') and token.isalpha():
        value = LATEX_COMMANDS.get(word, 0.0)
    elif token == '{' and prev_word in ('end', 'begin'):
        value = 6.8 if prev_word == 'end' else 0.75
    elif '</' in previous and word.isalpha() and not previous.endswith('>'):
        value = CLOSING_TAG_NAMES.get(word, 0.5)
    elif word.lower() == 'end':
        if prev_word.lower() in SPATIAL_END:
            value = -1.4
        elif previous.rstrip().endswith('{%'):
            value = 4.9
        elif previous.rstrip().endswith('<!--'):
            value = 2.3
        elif previous.isspace() or token.startswith('\t'):
            value = 0.9
        elif word != 'end':
            value = 0.5
    elif word == '-end':
        value = -1.7
    elif word.lower() in ('ended', 'ending'):
        value = -0.6
    elif word == 'up' and prev_word.lower() in ('end', 'ends', 'ended', 'ending'):
        value = -1.8
    elif word == 'of' and prev_word.lower() == 'end':
        value = 0.49
    elif '```' in token:
        value = 0.5 if token.startswith(' ') else 0.8
    elif word == 'endif':
        value = 3.5 if token.startswith(' ') else 1.7
    elif '[/' in token:
        value = 3.0
    elif '/>' in token:
        value = 0.6
    elif token == ';/' and previous.endswith('lt'):
        value = 5.3  # Entity-escaped closing opener: &lt;/
    return (doc, token), float(value)

programs.luna:
"""Recognize markup and LaTeX closers plus a few other source markers.

The rules focus on closing-tag openers and LaTeX commands; they also mark
code fences, completed tool calls, shell shebangs, and carriage returns.
"""

READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    token = tokens[-1]

    # A completed tool-call marker has a small, stable response.
    if token == "</tool_call>":
        return None, 0.67

    # HTML/XML closing-tag openers, sometimes attached to adjacent punctuation.
    if "</" in token:
        return None, 5.0

    previous = ""
    if (
        len(tokens) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    ):
        previous = tokens[-2]

    # LaTeX structural commands: \end, \right, \begin, \ge and \it.
    if previous.endswith("\\"):
        if token == "end":
            return None, 7.0
        if token == "right":
            return None, 3.5
        if token == "begin":
            return None, 0.8
        if token == "ge":
            return None, 1.0
        if token == "it":
            return None, 0.8

    # The first token inside a closing HTML element can be its tag name.
    if previous.endswith("</") and token == "a":
        return None, 1.2

    if token.strip() == "```":
        return None, 0.75

    # A shell script's shebang marker and a terminal's carriage-return update.
    if token.startswith("#!/"):
        return None, 0.8
    if token == "\r":
        return None, 0.7

    return None, 0.0

programs.sol:
"""Approximate a local spelling-boundary response.

An alphabetic token continuing an h/z-like ending gets a positive score,
strongest for u-led fragments (especially ul and uf). Common endings,
i followed by another vowel, and doubled fricatives suppress it. Other
consonant clusters get a weaker response. Only the preceding token is
remembered, and document boundaries clear it. Numerical strengths are
fitted approximations; detailed token-specific effects are not modeled.
"""
import math
import unicodedata

READS = ()
# Approximate corresponding Cyrillic and Arabic letters.
EQUIVALENT_GROUPS = {
    'a': 'ая', 'e': 'еэ', 'i': 'иыيی', 'o': 'оё', 'u': 'уюو',
    'h': 'хшщчحخهش', 'z': 'зжز', 'y': 'й',
}
EQUIVALENTS = {
    c: base for base, group in EQUIVALENT_GROUPS.items() for c in group
}
GAIN = {'h': (1.08, 1.30), 'z': (1.41, 1.90), 'x': (.77, 1.25),
        'j': (.50, .47), 'w': (.46, .61), 'y': (.49, .89), 'q': (.45, .45)}
VOWEL_SCORE = {'a': .31, 'e': .20, 'i': .56, 'o': .57, 'u': .98}
COMMON_ENDINGS = {'ing', 'ed', 'es', 'as', 'ard'}
LIQUID_CLUSTERS = ('bl', 'cl', 'fl', 'gl', 'pl',
                   'br', 'cr', 'dr', 'fr', 'gr', 'pr', 'tr')


def letter(c):
    c = c.lower()
    return EQUIVALENTS.get(c, unicodedata.normalize('NFD', c)[:1])


def preceding_strength(previous):
    final = letter(previous[-1])
    # Each pair is the strength for lowercase / uppercase endings.
    gain = GAIN.get(final, (0.0, 0.0))[previous[-1].isupper()]
    if gain:
        return gain
    tail = previous.lower()
    if tail.endswith('qu'):
        return .45
    if tail.endswith(LIQUID_CLUSTERS):
        return .15
    if tail.endswith(('sc', 'sk', 'sp', 'st')):
        return .11
    if tail[-1] in 'šşčçžř':
        return .60
    return 0.0


def fragment_score(token):
    first = letter(token[0])
    second = letter(token[1]) if len(token) > 1 else ''
    score = VOWEL_SCORE.get(first, .24 if first in 'lrwvf' else .10)
    if first == 'u':
        score += {'l': .77, 'f': .47, 'm': -.27, 'n': -.27}.get(second, 0.0)
    if first == 'i' and second and second in 'aeiou':
        score -= .64
    score -= .052 * max(0, len(token) - 3)
    score -= .23 * (len(token) == 1)
    score -= .60 * (token.lower() in COMMON_ENDINGS)
    score -= .57 * token.lower().startswith('ion')
    if token[0].isupper() and first in 'aeiou':
        score -= .12
    script = unicodedata.name(token[0], '')
    if 'CYRILLIC' in script or 'ARABIC' in script:
        score -= .14
    return score


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if token.isalpha() and previous:
        gain = preceding_strength(previous)
        if gain:
            score = fragment_score(token)
            if (letter(previous[-1]) in 'hzxs'
                    and token[0].lower() == previous[-1].lower()):
                score -= .38
            length = 0
            for c in reversed(previous):
                if not c.isalpha():
                    break
                length += 1
            value = 1.2 * gain * score * math.exp(-.14 * max(0, length - 2))
    return (doc, token), float(value)

"""Recognize a small mixture of formulaic text continuations.

Training examples span several formulaic text domains. This approximation
models negative responses in generated code, license/legal boilerplate, and
website metadata, plus a few structured transcript and mathematical markers.
It is selective: most tokens remain near zero, not all code or all headings.
Values are rounded training estimates. A 160-character suffix resets at
document boundaries. Many other lexical continuations are left unmodeled.
"""
import re

READS: tuple[str, ...] = ()

TRANSCRIPT_MARKERS = {
    '<think>': -0.32,
    '</think>': -0.32,
    '<tool_call>': -0.26,
    '</tool_call>': -0.16,
    '</tool_response>': 0.09,
    '<|im_end|>': 0.05,
    '<|endoftext|>': -0.015,
}

LABEL_ENDINGS = (
    'Challenge Level', 'Statutory Notes', 'Community Profile',
    'PPT Presentation', 'Code Examples',
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = (old + token)[-160:]
    word = token.strip()
    value = TRANSCRIPT_MARKERS.get(token, 0.0015)

    # Mathematica's textual box/list representation.
    if token == 'Box':
        if text.endswith('RowBox'):
            value = -1.03
        elif re.search(r'(Fraction|Superscript|Subscript)Box$', text):
            value = -0.75
    elif token == '[List' and old.endswith('Box'):
        value = -0.75
    elif token in ('["', '[') and old.endswith('[List'):
        value = -0.15

    # Qualified class names and generated source-code boilerplate.
    if token.startswith('.') and re.fullmatch(r'\.[A-Z]\w{3,}', token):
        if re.search(r'\.[a-z]\w*$', old):
            value = -0.28 if len(token) >= 10 else -0.16
    if token == '-doc' and old.endswith('-user'):
        value = -1.6
    if word == 'generated' and old.endswith(' @'):
        value = -0.55
    if word in ('SQLException', 'IOException') and old.endswith(' throws'):
        value = -0.6
    if word == 'License' and old.endswith('the "'):
        value = -1.7
    if word == 'required' and re.search(r'\bUnless$', old):
        value = -0.8
    if token == '.Tasks' and old.endswith('.Threading'):
        value = -1.4
    if token == '.Bundle' and old.endswith('.os'):
        value = -1.0
    if old.endswith(' super'):
        if token in ('.viewDidLoad', '.didReceiveMemoryWarning'):
            value = -2.5
        elif token == '.onCreate':
            value = -0.7

    # SQL schema conventions.
    if token == '_INCREMENT' and old.endswith('AUTO'):
        value = -1.1
    if token == '_RESULTS' and old.endswith('CHARACTER_SET'):
        value = -1.3
    if word == 'CHARSET' and old.endswith('DEFAULT'):
        value = -0.5
    if word == 'TRANSACTION' and old.endswith('START'):
        value = -1.3

    # Printed labels in tracebacks, legal citations and website metadata.
    if word == 'line' and old.endswith('",'):
        value = -0.4
    if word == 'App' and old.endswith('Vet.'):
        value = -0.75
    if token.startswith(' ') and any(text.endswith(s) for s in LABEL_ENDINGS):
        value = -0.65
    if token == 'udos' and old.endswith('K'):
        value = -1.6 if re.search(r'Followers:\s*\d+\s+K$', old) else -0.08
    if word == 'permalink' and old.endswith('[#'):
        value = -0.45
    if word == 'Views' and old.endswith(('\n', '\r')):
        value = -0.6
    if word == 'views' and re.search(r'\d+$', old):
        value = -0.35
    if token == 'itations' and old.endswith('Inv'):
        value = -1.05
    if token == 'otions' and old.endswith('Prom'):
        value = -1.4
    if token == 'ularity' and text.endswith('Popularity'):
        value = -0.5
    if word == 'Total' and old.endswith('['):
        value = -0.17
    if word == 'pages' and re.search(r'\d+$', old):
        value = -0.25

    # HTML head metadata and a Python source encoding declaration.
    if word == 'UTF' and old.endswith('charset="'):
        value = -1.5
    if word == 'utf' and re.search(r'coding:\s*$', old):
        value = -0.8
    if word == 'viewport' and old.endswith('<meta name="'):
        value = -1.7

    # Named web-service attribution/navigation templates.
    if word == 'TripAdvisor' and old.endswith('-'):
        value = -1.6
    if token == 'Mass' and old.endswith('Explore Brain'):
        value = -1.28
    if token == 'Share' and old.endswith('Upcoming Slide'):
        value = -0.7

    # Formulaic legal document titles and boilerplate headings.
    if word == 'Claims' and old.endswith('Veterans'):
        value = -0.94
    if token == 'CKET' and old.endswith('DO'):
        value = -1.4
    if token == 'jections' and old.endswith('Claim Re'):
        value = -0.7
    if token == 'ATIONS' and old.endswith('LABOR REL'):
        value = -1.0

    return (doc, text), float(value)

