"""Predict the typical small activation, with exceptions for chat-control tags.

In sampled training text, thought/tool-call tags tend negative, while message
and tool-response boundaries have smaller, different signed averages.
"""

READS = ()

THOUGHT_AND_TOOL_CALL = {
    "<think>", "</think>",
    "<tool_call>", "</tool_call>",
}
MESSAGE_BOUNDARIES = {"<|im_start|>", "<|im_end|>"}
TOOL_RESPONSE_END = "</tool_response>"
DOCUMENT_END = "<|endoftext|>"

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in THOUGHT_AND_TOOL_CALL:
        return None, -0.235
    if token == TOOL_RESPONSE_END:
        return None, 0.10
    if token in MESSAGE_BOUNDARIES:
        return None, 0.035
    if token == DOCUMENT_END:
        return None, -0.018
    return None, 0.00133

programs.sol:
"""A lexical HAVE-family detector, fitted to training activation averages.

Have/has/having give the largest responses; had, contractions, possession
verbs and listed translations are weaker. Capitalization and token-boundary
spelling change the strength. BEFORE/AFTER and the AVE fragment also respond.
One previous token is retained to recognize the suffix of haven't/hasn't/
hadn't, and is forgotten at document boundaries. Everything else is zero.
This approximates the dominant lexical spikes, not finer syntactic variation
or the many small background activations.
"""
READS = ()

# Other-language forms of 'have', plus English possession verbs.
POSSESSION = {
    'possess': 1.33, 'possesses': 1.20, 'possessing': 1.35,
    'possessed': 0.58,
    'haben': 0.88, 'habe': 0.79, 'hat': 0.21, 'hatte': 0.57,
    'hatten': 0.57, 'hast': 0.53, 'hath': 1.31,
    'avoir': 0.97, 'avons': 0.78, 'avez': 0.86, 'ont': 0.33,
    'avere': 1.19, 'hanno': 0.67, 'ha': 0.40,
    'tener': 0.98, 'tiene': 1.04, 'tienen': 1.07, 'tienes': 0.71,
    'tem': 0.36, 'hebben': 1.24, 'har': 0.24, 'hadde': 0.80,
    'иметь': 1.30, 'имеет': 1.03, 'имеют': 1.36,
    'có': 0.54,
    '具有': 0.89, '具备': 0.57, '拥有': 0.70, '擁有': 0.95,
}
NEGATIVE_HAVE = {'haven': 1.29, 'hasn': 1.16, 'hadn': 0.46}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = raw.strip()
    word = token.lstrip('._-(')
    lower = word.lower()
    spaced = raw[:1].isspace()
    capital = word != lower
    value = 0.0

    if lower == 'have':
        value = 3.90 if capital else (3.46 if spaced else 2.90)
        if token.startswith('.'):
            value = 4.05
        elif token.startswith('-'):
            value = 3.20
    elif lower == 'has':
        value = 1.42 if capital else (2.44 if spaced else 1.30)
        if token.startswith('.'):
            value = 1.35 if capital else 1.59
    elif lower == 'having':
        value = 3.14 if spaced else (3.50 if capital else 2.45)
    elif lower == 'had':
        value = 0.25 if capital else (1.02 if spaced else 0.72)
    elif lower in NEGATIVE_HAVE:
        value = NEGATIVE_HAVE[lower]
        if capital and lower == 'haven':
            value = 0.69
    elif lower in {"'ve", '’ve'}:
        value = 1.65 if lower[0] == "'" else 1.87
    elif lower in {"'t", '’t'}:
        value = {'haven': 0.86, 'hasn': 0.93, 'hadn': 0.37}.get(previous, 0.0)
    elif lower == 'before':
        value = 0.59
    elif lower == 'after':
        value = 0.88 if spaced or capital or token != word else 0.69
    elif lower in POSSESSION:
