    if spaced:
        if letter in 'OU':
            return -0.79
        if letter in 'EG':
            return -0.64
        if letter in 'IXQ':
            return -0.19
        if letter in 'CDKVWYZ':
            return -0.34
        if letter in 'AS':
            return -0.52
        return -0.44
    if letter == 'O':
        return -2.3
    if letter in 'AEGRU':
        return -1.9
    if letter in 'PXY':
        return -1.05
    return -1.48


def fragment_factor(previous, bare, attached):
    """A short fragment makes a case change more conspicuous."""
    length = min(6, max(1, sum(c.isalpha() for c in previous)))
    if bare:
        return (1.1, 1.1, 0.8, 0.6, 0.55, 0.45)[length - 1]
    if attached:
        return (1.35, 1.15, 1.05, 0.75, 0.7, 0.6)[length - 1]
    factor = (1.8, 1.3, 1.2, 1.1, 1.05, 1.05)[length - 1]
    if previous.startswith(' '):
        factor -= 0.3
    if any(c.isupper() for c in previous):
        factor += 0.25
    return factor


