    s = prefix.token_strings[-1]
    letters = ''.join(c for c in s if c.isalpha())
    bare = s == letters
    attached = s.strip() != letters
    same_document = len(prefix.token_strings) > 1 and (
        prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = prefix.token_strings[-2] if same_document else ''
    last = previous[-1:]
    lower_before = last.islower()

    # Short all-capital fragments inside a mixed-case word.
    if len(letters) in (2, 3) and letters.isupper():
        if bare and lower_before:
            value = -0.8 if len(letters) == 2 else -0.35
            return None, value * fragment_factor(previous, True, False)
        return None, 0.04 if len(letters) == 2 else 0.0
    if len(letters) == 2 and letters.istitle():
        return None, 0.08 if bare and not lower_before else 0.0
    if len(letters) != 1 or not letters.isupper():
        return None, 0.0
    if not same_document:
        return None, 0.10 if not attached else 0.0
    if lower_before:
        value = capital_strength(letters, not bare)
        value *= fragment_factor(previous, bare, attached)
        if attached:
            mark = s[:s.index(letters)]
            if mark in ('_', '/', '('):
                value *= 0.6
            elif mark in ('.', '-'):
                value *= 1.15
            elif mark == "'":
                value *= 1.8
        return None, value
    if last.isdigit():
        return None, -0.06 if attached else -0.24
    if last.isupper() or last in '.!?':
        return None, 0.0
    if last in '-_':
        return None, -0.17 if bare else -0.11
    if bare and (last.isspace() or last in '()[]{}"\'`'):
        return None, 0.0
    return None, -0.08

