    'correction': -0.37, 'corrections': -0.37,
    'typo': -0.64, 'flawed': -0.59,
    'accurate': -0.2, 'perfect': -0.22, 'right': -0.16,
    'errno': -0.57, 'perror': -0.45, 'strerror': -0.6,
    'stderr': -0.3,
    # Translations, including stems where a tokenizer splits the word.
    'ошиб': -2.46, 'ошибка': -1.55, 'шибка': -0.96,
    'правильно': -0.97, 'richtig': -0.97, 'fehler': -0.88,
    'erreur': -1.0, 'errores': -1.0, 'correctamente': -0.68,
    'salah': -1.36, 'sai': -1.1, 'đúng': -1.49, 'doğru': -0.94,
    '間違い': -2.15, '正しい': -1.13, '違': -0.63,
    '오': -0.9, '맞': -1.39, '妥': -0.8, '纠正': -0.85,
    '✓': -0.25, '✔': -0.25,
