def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    text = raw.strip()
    if text in {'错', '錯'}:
        return None, -4.8
    if text in {'错误', '錯誤'}:
        return None, -3.0
    if text in {'错了', '錯了'}:
        return None, -4.1
