        return None, value
    if any(c in text for c in '误誤'):
        return None, -1.5 if len(text) == 1 else -0.8
    if '正确' in text or '正確' in text:
        return None, -1.3 if len(text) == 2 else -1.0

    word = re.sub(r'^\W+|\W+$', '', text).strip('_')
    lower = word.lower()
    value = PULSES.get(lower, 0.0)
    if lower in {'error', 'errors'}:
        if word.istitle():
            value = -1.45
        elif word.isupper():
            value = -1.27
        elif not raw.startswith(' '):
            value = -1.52
        if text.startswith(('(', '.')):
            value += 0.2
    elif lower == 'err':
        if text.startswith('_'):
            value = -1.6
        elif word.istitle():
            value = -1.15
        elif word.isupper():
            value = -0.85
        elif not raw.startswith((' ', '\t', '.')):
            value = -0.66
    elif lower == 'errorf':
        value = -0.75
    elif lower.startswith('error') or word.endswith('Error'):
        value = -0.75
