"""Use a sparse, context-free word list for correctness and error terms.

Return negative values for error/wrongness words, smaller ones for correct or
related words, and zero for everything else. The lists name word families,
not token IDs.
"""

import re

READS = ()

STRONG_ERROR = (
    "error", "incorrect", "inaccur",
    "erratum", "errone", "неправ", "ошиб", "erreur", "fehler",
    "falsch",
)
STRONG_WRONGNESS = ("wrong", "mistake")
CORRECTION = ("correct",)
WEAK_ERROR = ("flaw", "typo", "falsely", "erro")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    split_case = re.sub(r"([a-z])([A-Z])", r"\1 \2", token)
    words = re.findall(r"[^\W\d_]+", split_case.lower())

    def has(terms):
        return any(
            word.startswith(term) for word in words for term in terms
        )

    if token.strip() in ("錯", "错"):
        return None, -4.50
    if has(STRONG_WRONGNESS):
        return None, -1.70
    if has(STRONG_ERROR) or any(
        term in token for term in ("間違", "錯", "错", "误")
    ):
        return None, -1.55
    if has(("corrected", "correctness")):
        return None, -0.52
    if has(CORRECTION) or any(
        term in token for term in ("正確", "正确", "正しく")
    ):
        return None, -1.10
    if "err" in words:
        return None, -1.00
    if token.isupper() and token.endswith("ERR"):
        return None, -0.90
    if has(("accur",)):
        return None, -0.25
    if has(("right",)):
        return None, -0.14
    if has(WEAK_ERROR) or any(term in token for term in ("违规", "不妥", "妥")):
        return None, -0.50
    return None, 0.0

