"""Approximate a word-level signal for pairs and comparisons, not digit counting.

'Two' is strongest, especially in 'between (the) two'. Pair words and
relational adjectives give smaller responses, strengthened by plural contexts
and weakened by singular ones. A few continuations of pair phrases also fire;
'and' following a pair cue is negative. Everything else defaults to zero.
The eight-token history resets at document boundaries. Values are approximate.
"""
READS = ()

TWO = {
    'two': 3.3, 'deux': 2.5, 'zwei': 2.5, 'twee': 2.0,
    'dois': 2.5, 'duas': 2.5, 'dos': 0.9, 'due': 0.25,
    'два': 2.7, 'две': 2.3, 'двух': 2.7, '두': 3.1,
}
PAIRS = {
    'both': 1.9, 'beide': 2.3, 'beiden': 2.6, 'ambos': 2.6,
    'pair': 1.2, 'pairs': 0.7, 'couple': 1.3, 'twice': 1.3,
    'twin': 1.3, 'twins': 1.3, 'dual': 0.9, 'mutually': 1.3,
    'between': 0.9, 'together': 0.9, 'respective': 1.9,
    'respectively': 1.3, 'entre': 0.4, 'zwischen': 0.7,
    'между': 0.7, '서로': 2.0, '함께': 0.9,
}
COMPARISONS = {
    'equal': 1.2, 'same': 0.9, 'identical': 0.9, 'similar': 0.9,
    'different': 0.9, 'distinct': 1.2, 'separate': 0.9, 'multiple': 0.9,
    'consecutive': 1.2, 'successive': 1.2, 'opposite': 0.7,
    'adjacent': 0.7, 'perpendicular': 0.7, 'independent': 0.7,
    'related': 0.4, 'parallel': 0.4, 'overlapping': 0.9,
    'complementary': 1.2, 'conflicting': 1.2,
}
OTHER = {
    'three': 0.8, 'four': 0.5, 'one': -0.08, 'each': -0.08,
    'sides': 0.6, 'parties': 0.5, 'halves': 1.1,
    '双': 0.95, '雙': 0.95, '相': 0.95, '同': 0.6,
    '双方': 2.2, '互相': 1.65, '相互': 1.2, '彼此': 1.2,
    '不同': 1.2, '不同的': 1.2, '同一': 1.2, '分别': 1.2,
}
LEXICAL = TWO | PAIRS | COMPARISONS | OTHER


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    previous = history[-1] if history else ''
    raw = prefix.token_strings[-1].strip()
    word = raw.lstrip('_-.').lower()
    value = LEXICAL.get(word, 0.0)
    if '两' in word or '兩' in word:
        value = 3.3
        if any(unit in word for unit in ('天', '月', '年', '周')):
            value = 1.3

    if word == 'two':
        value = 3.0
        if previous in {'the', 'these', 'those', 'any'}:
            value = 4.25
        elif previous in {'a', 'first', 'last', 'only', 'exactly', 'than', 'least'}:
            value = 2.15
        elif previous == 'or':
            value = 1.85
        elif previous in {'is', 'has', 'was', 'and'}:
            value = 2.55
        elif previous in {'are', 'were', 'of'}:
            value = 3.4
        if 'between' in history[-2:]:
            value = 6.9
        if not history:
            value = 6.7
    elif word in COMPARISONS:
        if previous in {'a', 'an'}:
            mild = word in {'similar', 'independent', 'multiple',
                            'perpendicular', 'same'}
            value -= 0.3 if mild else 0.8
        elif previous in {'is', 'has', 'was'}:
            value -= 0.25
        elif previous in {'are', 'were'}:
            value += 0.55
        elif previous == 'two':
            value += 1.7
        elif previous in {'both', 'three'}:
            value += 0.7
        elif previous == 'between':
            value += 2.1

    # Recognizable continuations, rather than a general semantic pair parser.
    if word == 'of' and previous in {'pair', 'couple', 'two', 'both'}:
        value = 1.3 if previous in {'pair', 'couple'} else 0.6
    elif word == 'the' and previous in {'between', 'both'}:
        value = 0.4 if previous == 'between' else 0.2
    elif word == 'them' and previous == 'between':
        value = 1.95
    elif word == 'and':
        for age, old in enumerate(reversed(history), 1):
            if old in {'two', 'both', 'between'}:
                value = -0.2 if old == 'between' else -0.6 / age
                break
    if raw.startswith(('_', '.', '-')):
        value *= 0.65
    return (doc, (history + (word,))[-8:]), float(value)

