ONSET = {
    's': (0.01, 0.92),
    'z': (-0.01, 0.58),
    'st': (-0.19, 1.32),
    'sh': (-0.65, 1.16),
    's_cluster': (0.02, 1.18),
    'long_s': (-0.31, 1.53),
    'cyr_s': (-0.56, 1.22),
    'cyr_z': (-0.55, 1.06),
    'cyr_sh': (-0.82, 1.20),
    'cyr_cluster': (-1.21, 1.75),
    'cyr_other': (-0.23, 0.35),
    'greek': (-0.06, 0.27),
    'kana': (-0.20, 0.73),
}
# Fragment lengths 1, 2, 3, 4, 5+.
LENGTH = {
    'latin': (0.82, 1.00, 0.75, 0.41, 0.19),
    'st': (0.00, 1.00, 0.87, 0.55, 0.24),
    'cyr': (1.00, 0.75, 0.51, 0.33, 0.31),
    'syllable': (1.00, 0.60, 0.26, 0.15, 0.00),
}
# Last-letter classes: scores for an isolated letter and a longer word fragment.
ENDINGS = (
    ('aouαηιοωυаіиоуыюяїє', 1.74, 1.55),
    ('i', 1.24, 1.32),
    ('eеэε', 1.30, 0.79),
    ('yйь', 0.35, 0.31),
    ('kgкг', -1.91, -2.15),
    ('ptbdптбд', -0.80, -1.05),
    ('mnмн', -0.44, -0.66),
    ('rlрл', -0.21, -0.40),
    ('fvфв', -0.47, -0.87),
    ('hх', -0.55, -1.40),
    ('sſzсзшщжσςζß', 0.04, -0.22),
    ('cwцч', -0.41, -0.63),
)

@lru_cache(maxsize=4096)
def base(c):
    return unicodedata.normalize('NFD', c).lower()[:1]

@lru_cache(maxsize=8192)
def ending(token):
    if not token:
        return 0.17
    c, stem = base(token[-1]), len(token.strip()) > 1
    score = 0.23 if token[-1].isalpha() else 0.17
    for letters, single, longer in ENDINGS:
        if c in letters:
            score = longer if stem else single
            break
    else:
        if token[-1].isdigit():
            score = 0.24
        elif token[-1] in 'クグキギ':
            score = -2.15
        elif token[-1] in 'トドツヅ':
            score = -1.05
        elif token[-1] in 'ンん':
            score = -0.66
        elif token[-1] in 'ナニヌネノマミムメモラリルレロガビセ':
            score = 1.55
        elif token[-1] in 'アイウエオ':
            score = 0.31
    return score * (0.58 if len(token.strip()) >= 5 else 1.0)

@lru_cache(maxsize=8192)
def onset(token):
    spaced = bool(token) and token[0].isspace()
    punct = bool(token) and token[0] in '.-/_'
    word = token.lstrip() if spaced else token.lstrip('.-/_')
    if not word:
        return None
    c, n = base(word[0]), len(word)
    family = 'latin'
    if c in 'szſ':
        kind = 'z' if c == 'z' else 's'
        if c == 'ſ':
            kind = 'long_s'
        elif c == 's' and len(unicodedata.normalize('NFD', word[0])) > 1:
            kind = 'sh'
        elif word[:2].lower() in ('sh', 'st'):
            kind = word[:2].lower()
        elif word[:2].lower() in ('sp', 'sk', 'sn'):
            kind = 's_cluster'
        if kind == 'st':
            family = 'st'
    elif c in 'сшщзчцж':
        family = 'cyr'
        kind = {'с': 'cyr_s', 'з': 'cyr_z', 'ш': 'cyr_sh',
                'щ': 'cyr_sh'}.get(c, 'cyr_other')
        if c == 'с' and n > 1 and base(word[1]) in 'тскпнмв':
            kind = 'cyr_cluster'
    elif c in 'σςζ':
        kind, family = 'greek', 'syllable'
    elif word[0] in 'さしすせそざじずぜぞサシスセソザジズゼゾ':
        kind, family = 'kana', 'syllable'
    else:
        return None
    offset, sensitivity = ONSET[kind]
    scale = LENGTH[family][min(n, 5)-1]
    if word[0].isupper():
        scale *= (0.90, 0.57, 0.30, 0.23, 0.12)[min(n, 5)-1]
    if spaced:
        scale *= 0.105 if n <= 2 else 0.009
    elif punct:
        scale *= 0.43 if n <= 2 else 0.013
    if token == '.S':  # A dotted capital initial, notably U.S.
        offset, sensitivity, scale = 0.15, 0.58, 1.0
    return offset * scale, sensitivity * scale


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    features = onset(token)
    value = 0.0 if features is None else features[0] + features[1] * ending(previous)
    return (doc, token), float(value)

programs.luna:
"""Recognize two recurring spellings that strongly move this component.

The component is usually quiet.  It drops sharply on the ``ster`` piece of
the title *American Gangster*, and rises on the abbreviation ``U.S.``.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[1] != document:
        before = ""
    else:
        before = carry[0]

    text = before + token
    value = 0.0
    if token == "ster" and before.endswith("American Gang"):
        value = -3.2
    elif token == ".S" and before.endswith("U"):
        value = 1.0

    return (text[-40:], document), float(value)

programs.sol:
"""A token-shape detector of question and exclamation punctuation.

Bare marks have a large positive response; repetition, attached punctuation
and merged newlines weaken it. Fullwidth marks respond less strongly.
Code operators and markup have separate, weaker responses. This detects
punctuation, not whether the text semantically asks a question.
A small early-document boost decays over forty tokens. Other tokens get
zero, omitting their small word-specific activations.
"""
import math

READS = ()
MARKS = frozenset('!?！？؟')
NORMALIZE = str.maketrans({'！': '!', '？': '?', '؟': '?'})


def punctuation_value(token):
    if not any(c in MARKS for c in token) or any(c.isalnum() for c in token):
        return 0.0
    if '<!--' in token or '#!' in token:
        return 0.0
    s = token.translate(NORMALIZE).strip()
    bang = '!' in s
    newline = '\n' in token
    if '!=' in s:
        return 0.18 if token.startswith(' ') else 0.68
    if '<?' in s or '?>' in s:
        return 0.30
    if '！' in token or '？' in token:
        if newline:
            return 0.40
        if s in ('!', '?'):
            return 0.94 if bang else 0.87
        return 0.68 if all(c in '!?' for c in s) else 0.55
    if s in ('!', '?'):
        if newline:
            return (0.80 if token.count('\n') > 1 else 0.67) if bang else 0.52
        if token.startswith(' '):
            return 1.20 if bang else 1.23
        return 1.37 if bang else 1.20
    if all(c in '!?' for c in s):
        if '!' in s and '?' in s:
            return 1.35
        if newline:
            return 0.74 if len(s) == 2 else 0.55
        return (1.25 if len(s) == 2 else 1.02) if bang else 0.80
    if bang and '[' in s:
        return 0.58
    if bang and '(' in s:
        return 1.04 - 0.10 * token.startswith(' ')
    if s.endswith('!') or s.endswith('?'):
        return (0.90 if bang else 0.67) if newline else (1.12 if bang else 1.25)
    if newline:
        return 0.62 if bang else 0.35
    return 0.86 if bang else 0.60


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = carry[1] + 1 if carry is not None and carry[0] == doc else 0
    value = punctuation_value(prefix.token_strings[-1])
    if value >= 0.4 and position:
        value += 0.25 * math.exp(-position / 40.0)
    return (doc, position), float(value)

"""Approximate a mainly Latin w-spelling feature seen in training activations.

Normalize fullwidth w/W and remove leading separators. Short w-ending
fragments are strongest, with ew stronger than aw or ow. Listed familiar
word spellings are attenuated; new/how remain positive, now/know/show/view
are nearly silent. Uppercase w-ending strings have their own level.
The allow family and ews/aws/ows are positive even though w is not final.
A bare w is stronger after a letter in the same document. Nothing else
uses context. Unmatched tokens get zero (long ASCII w-endings get 0.2).
"""

READS = ()

# Complete-word spellings, rather than short spelling fragments.
WORDS = set('''
new how few knew grew drew crew brew blew flew skew law saw raw draw
straw flaw claw thaw low flow slow grow throw glow
row allow follow hollow below yellow fellow shallow pillow willow
window widow shadow snow bow brow cow tow pow wow arrow narrow borrow
sorrow tomorrow review view preview interview overview andrew matthew
'''.split())
QUIET = set('now know show view review below yellow follow tomorrow shadow'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry and carry[0] == doc else ''
    s = prefix.token_strings[-1].replace('ｗ', 'w').replace('Ｗ', 'W')
    word = s.lstrip(' \t\r\n./_-([{=,;:&*+"\'')
    w = word.lower()
    value = 0.0
    if w in ('ews', 'aws', 'ows'):
        value = {'ews': 2.1, 'aws': 1.1, 'ows': 0.8}[w]
    elif w.startswith('allow'):
        value = 0.75
    elif word.isascii() and w.endswith('w'):
        if w in QUIET:
            value = 0.04
        elif w in ('new', 'how', 'law', 'saw'):
            value = 1.05
        elif w in ('jaw', 'cow', 'tow', 'pow', 'brow', 'sew', 'chew', 'slew'):
            value = 1.7
        elif w in ('low', 'draw', 'throw'):
            value = 0.2
        elif w in WORDS:
            value = 0.8 if w.endswith(('ew', 'aw')) else 0.6
        elif w == 'w':
            value = 4.25 if s == word and prev[-1:].isalpha() else 2.4
        elif w == 'ww':
            value = 2.0
        elif w == 'www':
            value = 0.1
        elif word.isupper() and len(word) >= 3:
            value = 1.5
        elif len(w) <= 4:
            if w.endswith('iew'):
                value = 3.0
            elif w.endswith('ew'):
                value = 4.1
            elif w.endswith('aw'):
                value = 2.7
            elif w.endswith('ow'):
                value = 1.5
            elif w.endswith('fw'):
                value = 5.6
            elif w.endswith('gw'):
                value = 4.7
            else:
                value = 3.2 if s != word else 3.8
        else:
            value = 0.2
    return (doc, s), float(value)

programs.haiku:
"""Letter-w detector for layers.0.mlp.down_proj:1898 (Qwen3-1.7B, layer 0).

This component sits in layer 0, so it reads almost nothing but the current token. It
fires on the letter "w" as it is spelled in that token:

- a bare "w" or "W" (strongest, about 3; about 2.4 when the token has a leading space,
  as in " W");
- a short fragment of up to three letters spelled with w, such as "sw", "tw", "gew",
  "rew", "aw", "ew": about 3. The fragment "ow" gets about 1.5;
- a whole English word whose w is a plain /w/ sound: new, how, few, law, row, saw, knew,
  window, crew, and so on: about 1;
- the "allow" family (allow, allows, allowed): about 0.7;
- other longer words ending in w: about 0.1;
- words where the w is silent or the final "ow" is the long o, such as now, know, show,
  view, follow, below, flow, grow: 0.

Every other token predicts 0. Predictions are in the activation's own units (the size of
the component's contribution), so the largest values are the bare w tokens.
"""

READS = ()

SINGLE_W = 3.0           # token is just w / W, no leading space
SINGLE_W_SPACE = 2.4     # token is just w / W with a leading space, e.g. " W"
FRAGMENT = 3.0           # a fragment of up to three letters ending in w
OW_FRAGMENT = 1.5        # the fragment "ow" (and "OW")
PLAIN_W_WORD = 1.0       # whole word whose final w is a plain /w/ sound
ALLOW_FAMILY = 0.7       # allow, allows, allowed, allowing
OTHER_W_WORD = 0.1       # any other longer word ending in w

PLAIN_W_WORDS = {
    "new", "how", "few", "law", "row", "saw", "raw", "knew", "allow", "window", "crew",
    "grew", "flew", "blew", "threw", "brew", "renew", "sew", "cow", "bow", "tow", "pow",
    "flaw", "throw",
}

SILENT_OR_LONG_O_WORDS = {
    "now", "low", "know", "show", "view", "follow", "below", "yellow", "review", "draw",
    "flow", "grow", "slow", "snow", "blow", "shadow", "overview", "preview", "interview",
    "shows", "knows", "shown", "known", "grown", "own", "tomorrow", "sorrow",
}


def _letters(text):
    return "".join(c for c in text.strip().lower() if c.isalpha())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    letters = _letters(token)
    if "allow" in letters:
        return carry, ALLOW_FAMILY
    if not letters.endswith("w"):
        return carry, 0.0
    if letters == "w":
        return carry, SINGLE_W_SPACE if token.startswith(" ") else SINGLE_W
    if letters in PLAIN_W_WORDS:
        return carry, PLAIN_W_WORD
    if letters in SILENT_OR_LONG_O_WORDS:
        return carry, 0.0
    if len(letters) <= 3:
        return carry, OW_FRAGMENT if letters == "ow" else FRAGMENT
    return carry, OTHER_W_WORD

programs.sol:
"""A lexical detector for loops and, more weakly, circular structures.

The strongest negative response is to 'loop' and Chinese loop/ring words.
Cycles, rings, hooks, circulation, chains, iteration and environment words
are weaker cues. Unfinished word pieces can also fire; isolated
suffixes are weaker.
It checks the preceding token for split spellings, strengthens main/event/
infinite loops, and carries a weaker response onto a following 'of'.
The carry resets at document boundaries. This is not a sentence-level
judgement about whether something really repeats.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('_-.(')
    # A byte fragment may have just completed a ring/circulation character.
    if '\ufffd' in token:
        completed = prefix.text_prefixes[-1][-1:]
        if completed in {'环', '환'}:
            word = completed
    lower = word.lower()
    previous = ''
    if (prefix.position and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2].lower()
    value = 0.0
    if lower == 'loop':
        value = -7.8 if token[:1] in '_-' else -7.5
        if token.startswith('.'):
            value = -6.0
        if previous.strip() in {'main', 'event', 'infinite'}:
            value -= 1.0
    elif lower == 'loops':
        value = -6.5
    elif lower == 'looping':
        value = -5.8
    elif lower == 'ops' and previous.strip().lstrip('_-.(') == 'lo':
        value = -7.7  # Lo + ops is a split spelling of loops.
    # Chinese ring, circulation, and closed-loop words.
    elif word in {'环', '環', '循环', '闭环'}:
        value = -7.4
    # Rebirth, halo, link, and environmental-protection compounds.
    elif word in {'轮回', '光环', '环节', '环保'}:
        value = -1.8
    elif word == '循':
        value = -3.3
    elif word in {'迴', '环比'}:
        value = -2.8
    elif lower in {'cyclic', 'yclic'}:
        value = -1.9
    elif lower in {'cycle', 'ciclo', 'цикл'}:
        value = -1.5
    elif lower in {'cycles', 'cycling'}:
        value = -1.3
    elif lower in {'cyc', 'cycl', 'ycler'}:
        value = -1.2
    elif lower in {'ring', 'rings', 'hoop', 'earrings', 'vòng'}:
        value = -1.5 if lower != 'rings' else -1.2
        if token == 'ring':  # Often a suffix rather than a separate word.
            value = -0.5
        elif word == 'RING':
            value = -0.2
    elif lower == 'mainloop':
        value = -1.6
    elif lower == 'circulating':
        value = -2.3
    elif lower in {'circ', 'irc', 'circular', 'ircular',
                    'circulation', 'circulated'}:
        value = -0.65 if token == 'circ' else -1.2
    elif lower == 'circum':
        value = -1.0
    elif lower in {'circuit', 'circuits', 'circus'}:
        value = -0.5
    elif lower in {'hook', 'hooks', 'hooked'}:
        value = -1.5 if lower == 'hooked' else -1.1
    elif lower in {'chain', 'chains', 'wheelchair', 'environmental'}:
        value = -0.6
    elif lower in {'iter', 'iterate', 'iteration', 'iterations', 'iterating'}:
        value = -1.3 if lower == 'iterate' else -0.65
        if token == 'iter':
            value = -0.1
    elif lower in {'circle', 'circles'}:
        value = -0.25
    elif lower.startswith('recycl'):
        value = -0.4
    elif lower in {'environment', 'environments'}:
        value = -0.3
    elif lower in {'environ', 'viron', 'lifecycle', 'infinite',
                    'infinitely', 'indefinitely', 'repetitive'}:
        value = -0.7
    elif word in {'环境', '環境', '环境保护', '链', '鏈', '周期', '圈', '生态环境'}:
        value = -0.8
    elif word in {'链条', '环绕', '环卫'}:
        value = -1.8
    elif word == '环球':
        value = -1.1
    elif token in {' Lo', 'Lo', '-lo'}:
        value = -1.1 if token == ' Lo' else -0.8
    # Korean syllables used in order, circulation, and repetition words.
    elif word == '순':
        value = -2.2
    elif word in {'환', '반'}:
        value = -2.0 if '\ufffd' in token else -1.4
    elif lower == 'ик' and previous.endswith('ц'):
        value = -1.3
    if lower in {'ed', 'ing'} and previous.strip() == 'loop':
        value = -3.2  # Split loop-ed or loop-ing.
    document = int(prefix.document_ids[-1])
    if lower == 'of' and carry is not None and carry[0] == document:
        value = 0.4 * carry[1]
    return (document, value), float(value)

programs.haiku:
"""Cyclic-repetition word detector: negative on words for loops, cycles and rings."""
READS = ()

LOOP = -7.5       # 'loop', 'loops', 'looping', '_loop' ...; and Chinese 环 / 環 ('ring, loop')
CYCLE = -1.4      # cycle, ring, circular, hook ...
WEAK = -0.5       # chain, circuit, iterate, environment ...
LOOP_CHARS = {'环', '環', '循', '迴'}
CYCLE_WORDS = {'cycle', 'cycles', 'cyclic', 'cycling', 'cycl', 'ring', 'rings',
               'circular', 'circ', 'circum', 'circulating', 'circulation',
               'hook', 'hooks', 'hooked'}
WEAK_WORDS = {'circuit', 'circuits', 'chain', 'chains', 'iter', 'iterate', 'iteration',
              'iterations', 'iterator', 'iterable', 'environmental', 'environ'}

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = ''.join(c for c in s.lower() if c.isalpha())
    if 'loop' in w or s.strip() in LOOP_CHARS:
        return None, LOOP
    if w in CYCLE_WORDS:
        return None, CYCLE
    if w in WEAK_WORDS:
        return None, WEAK
    return None, 0.0

programs.sol:
"""Approximate resemblance, role-description and resulting-state phrases.

'Looks/feels/seems like' gets a strong negative response, ordinary 'like'
a weaker one, and preference ('I like', 'would like') a positive one.
'As' after role/description verbs and 'into' after transformation verbs
are related negative cues. Intervening words weaken the verb cue.
The article 'a/an' after 'like' gets a smaller negative continuation.
Only a 100-character trailing buffer is kept; documents reset it.
"""
import re

READS = ()


def verbs(roots):
    """Regular English present, past and -ing forms."""
    result = set()
    for root in roots.split():
        base = root[:-1] if root.endswith('e') else root
        result.update((root, root + 's', base + 'ing',
                       root + ('d' if root.endswith('e') else 'ed')))
    return result


FEEL = set('feel feels felt feeling'.split())
SENSE = verbs('look sound taste smell seem')
ACT = verbs('act behave')
TREAT = verbs('treat')
TURN = verbs('turn')
TRANSFORM = verbs('convert transform evolve shape translate')
LIKE_CUES = [(FEEL, 7.5), (SENSE, 6.7), (ACT, 5.3), (TREAT, 5.8),
             (set('shaped reads reading'.split()), 4.5),
             (set('appear appears appeared work works worked read'.split()), 3.2)]
AS_CUES = [(set('seen regarded treated viewed perceived'.split()), 2.5),
           (verbs('serve'), 1.8), (TREAT, 2.0),
           (set('see sees view views interpreted recognized recognised played '
                'plays feel felt seem appears appear portrayed'.split()) | ACT, 1.6),
           (set('considered classified depicted understood emerged operate'.split()), 1.2),
           (set('used use described expressed represented worked working '
                'identified presented termed count counted read role'.split()), 0.8)]
COPULA = set("is are was were be been being 's ’s not nothing".split())


def cue(words, groups, decay, geometric=False):
    """Use the nearest recognized verb; weaken it with word distance."""
    for distance, word in enumerate(reversed(words)):
        for group, size in groups:
            if word in group:
                return (size * decay ** distance if geometric
                        else max(1.0, size - decay * distance))
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text, previous, last_value = '', '', 0.0
    if carry is not None and carry[0] == doc:
        _, text, previous, last_value = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if word in ('like', 'as', 'into', '.into', '_into'):
        clause = re.split(r'[.!?\n]', text)[-1].lower()
        words = re.findall(r"[a-z]+(?:['’][a-z]+)?", clause)
    if word == 'like':
        strength = cue(words[-4:], LIKE_CUES, 1.3)
        direct = cue([previous], LIKE_CUES, 1.3)
        if direct is not None:
            strength = direct
        elif words and cue(words[-1:], LIKE_CUES, 1.3) is not None:
            strength *= 0.5  # A split word gives a weaker cue.
        if previous in ('more', 'just') and len(words) > 1:
            modified = cue(words[-2:-1], LIKE_CUES[:3], 1.3)
            if modified is not None:
                strength = modified - 0.3
        value = -0.95
        if previous in COPULA:
            value = -1.8
        elif previous == 'more':
            value = -3.5
        elif previous == 'i':
            value = 1.0
        elif previous in ('would', "'d", '’d'):
            value = 0.5
        elif previous in ('you', 'we', 'they', 'he', 'she'):
            value = -0.1
        elif previous in ('something', 'things'):
            value = -0.2
            if strength is not None:
                strength = min(strength, 2.5)
        if strength is not None:
            value = -strength
    elif word == 'as':
        strength = cue(words[-6:], AS_CUES, 0.65, geometric=True)
        value = -(strength or 0.08)
        if previous in ('known', 'well', 'such', 'that'):
            value = 0.0
        elif previous in ('far', 'soon', 'long', 'much', 'so'):
            value = 0.3
        elif token.strip() == 'As':
            value = 0.2
        elif not token.startswith(' '):
            value = 0.03
    elif word in ('into', '.into', '_into'):
        strength = cue(words[-6:], [(TURN, 3.3), (TRANSFORM, 2.3)], 0.2)
        value = -max(1.1, strength or 1.1)
    elif word in ('-like', '_like'):
        value = -1.3
    elif word == 'out' and previous in TURN:
        value = -0.9
    elif word in ('como', 'comme', 'als', 'như') and token.startswith(' '):
        value = -0.8  # Comparison/role markers in other languages.
    elif word == 'unlike':
        value = -0.4
    elif word in ('resemble', 'resembles', 'resembling', 'resembled'):
        value = -1.5
    elif word == 'liked':
        value = 1.8 if previous == 'i' else 0.8
    elif word in ('a', 'an') and previous == 'like':
        value = -0.55 + 0.08 * min(0.0, last_value)
    return (doc, (text + token)[-100:], word, value), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:1902 -- a 'comparison / change / role' preposition detector.

What it does: this component is almost silent everywhere except on the English prepositions
"like", "into" and "as" (plus a few foreign equivalents such as French "comme", Spanish
"como", German "als"). On those words it goes negative, and how negative depends on the
word just before:

  * "like" meaning "resembling" after a verb of appearance -- "it looks like", "seems like",
    "feel like", "sounds like", "tastes like", "behaves like" -- is the strongest case (about -7),
    as is "more like" / "less like" (about -5). Other "like" after a noun or "is" or "just"
    is moderately negative (about -1.5). "would like" (the verb "to like") is slightly positive.
  * "into" after a verb of change -- "turned into", "converted into", "translate into",
    "transform into" -- is about -2.8; other "into" is about -1.
  * "as" after a verb of treating or role -- "served as", "regarded as", "treated as",
    "seen as", "acts as", "considered as" -- is about -2; after "used", "described",
    "expressed", "counted", or a pronoun ("treat it as") it is about -0.8. Other "as"
    (", as", "as well as", "as far as", "such as") is 0.

Everywhere else the program predicts 0. The real activation there is small noise.

The lists are short word lists, not learned weights. The program reads only the current token
and the one before it, so it is causal and needs no carry.
"""

READS = ()

LIKE = {" like", "like", " Like", "-like"}
LIKE_FOREIGN = {" comme", " como", " als", " như", " gibi"}
INTO = {" into", "into", " Into", "Into"}
AS = {" as", "as", " As"}

# 'X like' where X is a verb of seeming or appearance
SEEM = {" looks", " look", " looked", " looking", " seems", " seem", " seemed", " sounds",
        " sound", " sounded", " feel", " feels", " felt", " feeling", " tastes", " behaves",
        " behave", " acts", " act"}
MORE = {" more", " less"}
LIKING = {" would"}  # 'would like' = the verb 'to like', slightly positive

# 'X into' where X is a verb of change
CHANGE = {" turn", " turns", " turned", " turning", " convert", " converted", " converting",
          " translate", " translated", " transform", " transformed", " transforms", " evolve",
          " evolved", " become", " became", " becomes"}

# 'X as' where X is a verb of treating, regarding or serving in a role
ROLE = {" served", " serve", " serves", " serving", " seen", " regarded", " regard", " treated",
        " treat", " treats", " treating", " act", " acts", " acted", " acting", " considered",
        " consider", " recognized", " recognize", " viewed", " view", " construed",
        " interpreted", " played", " appear", " appears", " appeared", " behaves", " perceived",
        " classified", " see", " feel"}
# weaker 'as' cases: 'used as', 'described as', or 'as' after a pronoun
WEAK_AS = {" used", " described", " expressed", " counted", " it", " this", " them", " me"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in LIKE:
        if prev in SEEM:
            v = -7.0
        elif prev in MORE:
            v = -4.8
        elif prev in LIKING:
            v = 0.6
        else:
            v = -1.5
    elif tok in LIKE_FOREIGN:
        v = -1.0
    elif tok in INTO:
        v = -2.8 if prev in CHANGE else -1.0
    elif tok in AS:
        if prev in ROLE:
            v = -2.0
        elif prev in WEAK_AS:
            v = -0.8
        else:
            v = 0.0
    else:
        v = 0.0
    return carry, float(v)

programs.luna:
"""Use a few familiar relation words and their immediate phrase context.

"Like" is positive after "would" and strongly negative after look/sound cues;
"into" is more negative after change verbs; "as" varies with role and time
phrases, and "out" is negative after "turn". Capitalized "As" and "during"
get small positive values. Everything else is predicted as zero.
"""
READS = ()

LOOKING = {"look", "looks", "sound", "sounds", "seem", "seems"}
CHANGE = {
    "turn", "turns", "turned", "transform", "transforms", "transformed",
    "convert", "converts", "converted", "translate", "translates", "translated",
}


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids[-1]
    recent = [
        prefix.token_strings[i].strip().casefold()
        for i in range(max(0, t - 3), t + 1)
        if prefix.document_ids[i] == doc
    ]
    word = recent[-1]
    surface = prefix.token_strings[-1].strip()
    previous = recent[-2] if len(recent) > 1 else ""
    before = recent[-3] if len(recent) > 2 else ""
    third_back = recent[-4] if len(recent) > 3 else ""

    if surface == "As":
        return None, 0.25
    if word == "during":
        return None, 0.09

    if word == "like":
        if previous == "would" or previous.endswith(("'d", "’d")):
            return None, 1.1
        if previous in LOOKING or (previous == "more" and before in LOOKING):
            return None, -6.8
        if previous == "it" and before == "at" and third_back in LOOKING:
            return None, -4.4
        if previous in {"treated", "regarded"}:
            return None, -5.8
        return None, -1.1

    if word == "into":
        if any(token in CHANGE for token in recent[-4:-1]):
            return None, -2.4
        return None, -1.0

    if word == "as":
        if previous in {"soon", "far", "long"} and before == "as":
            return None, 0.3
        if previous == "well" and before == "as":
            return None, 0.0
        if previous in {"treated", "served", "serves"}:
            return None, -1.8
        if previous in {"used", "expressed", "described", "defined", "taken", "written"}:
            return None, -0.8
        if previous == "of" and before in {"think", "thought"}:
            return None, -0.8
        return None, -0.13

    if word == "out":
        if previous in {"turned", "turns", "turn"}:
            return None, -1.0
        if previous in {"ed", "s"} and before == "turn":
            return None, -1.0
    return None, 0.0

programs.sol:
"""Local negation and continuation, especially in contrast constructions.

'But also' and 'but not' are the strongest signals. Qualifying adverbs
respond more weakly. Recent conjunctions still affect a modifier after a
short interruption; negation decays faster than addition. Auxiliary
negation, additive idioms and common translated markers have explicit
response levels. These lexical rules do not interpret a sentence's truth
or meaning. Memory holds four tokens and resets on a document change.
"""
READS = ()

# Ordinary response and extra response immediately after 'but'.
MARKERS = {
    'not': (0.45, 6.5), 'also': (0.2, 8.2), 'never': (0.76, 4.5),
    'then': (0.64, 1.55), 'still': (0.0, 4.5), 'now': (0.15, 3.5),
    'rather': (-0.25, 6.0), 'only': (-0.08, 4.4), 'instead': (-0.25, 4.4),
    'no': (-0.08, 2.8), 'yet': (0.68, 1.8),
}
QUALIFIERS = set('neither none nothing without just more later again'.split())
AUXILIARIES = set(
    'is are was were has have had do does did will would can could '
    'may might should must'.split()
)
NEGATIVE_STEMS = set(
    'don doesn didn won wouldn haven hasn can couldn isn wasn aren '
    'weren shouldn hadn ain n'.split()
)
CONJUNCTIONS = {'but': 1.0, 'while': 0.55, 'whilst': 0.55,
                'though': 0.6, 'although': 0.6, 'yet': 0.6, 'and': 0.15}
# Translated negation/addition: ordinary response, response after contrast.
TRANSLATIONS = {
    # 'not/no' in Russian, German, French, Portuguese and Chinese.
    'не': (0.4, 4.3), 'nicht': (0.5, 2.2), 'pas': (0.0, 1.3),
    'não': (0.2, 0.9), '不': (0.3, 4.2), '没有': (0.1, 1.3),
    # 'also' in German, Russian, French, Spanish, Portuguese and Italian.
    'auch': (0.85, 3.7), 'также': (0.2, 4.6), 'aussi': (0.65, 7.2),
    'también': (1.3, 6.7), 'também': (0.8, 2.2), 'anche': (0.3, 1.7),
    # Chinese 'not yet', 'still', 'cannot'; Chinese/Japanese addition.
    '未': (0.0, 1.9), '仍然': (0.3, 1.9), '不能': (0.1, 1.4),
    '也': (0.75, 3.9), '又': (1.1, 4.4), 'も': (0.55, 1.3),
}
# Familiar translations of 'but', 'though', and related conjunctions.
FOREIGN_CONTRASTS = {'но', 'aber', 'mais', 'pero', 'sino', 'mas', 'ma',
                     '但', '但是', '不过', '可是', '但却', '然而', '虽', '却'}
PHRASES = {('well', 'as'): 1.75, ('as', 'well'): 0.49,
           ('no', 'longer'): 1.0, ('why', 'not'): 1.2, ('see', 'also'): 1.7,
           ('а', 'также'): 2.6, ('но', 'и'): 2.3, ('sino', 'también'): 2.9}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry and carry[0] == doc else ()
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = history[-1].strip().lower() if history else ''
    contracted = token.lower() in ("'t", '’t') and prev in NEGATIVE_STEMS
    base, gain = MARKERS.get(word, (0.0, 0.0))
    modifier = word in MARKERS or word in QUALIFIERS or word.endswith('ly')
    if word in QUALIFIERS or (word.endswith('ly') and word not in MARKERS):
        gain = 2.3
    elif word in AUXILIARIES:
        gain = 1.4
    elif word in ('with', 'in', 'at', 'this', 'the', 'as'):
        gain = 2.3 if word == 'with' else 0.7
    if word == 'not':
        if prev in ('is', 'are', 'were', 'has', 'have', 'had', 'to'):
            base = 0.1
        elif prev in ('do', 'does', 'did', 'need'):
            base = 0.8
        elif prev in ('was', 'might', 'may', 'could', 'can'):
            base = 0.25
        elif prev == 'must':
            base = 1.6
        elif prev == 'or':
            base = -1.2
            if any(t.strip().lower() == 'whether' for t in history):
                base = -1.8
    if contracted:
        if prev in ('don', 'doesn', 'didn'):
            base, gain = 1.25, 5.5
        else:
            base, gain = 0.85, 2.7
    if word == 'also':
        if prev in ('are', 'were', 'have', 'has', 'can', 'could'):
            base = -0.2
        elif token.strip() == 'Also':
            base = -0.4
    if word == 'additionally':
        base = -1.35 if token.strip()[0].isupper() else -0.5
        gain = 5.0

    decay = (1.0, 0.55, 0.38, 0.25)
    if word == 'not' or contracted:
        decay = (1.0, 0.4, 0.14, 0.06)
    strength = 0.0
    for distance, earlier in enumerate(reversed(history)):
        old = earlier.strip().lower()
        if old.endswith('but') and not old[:-3].isalpha():
            old = 'but'
        if old in CONJUNCTIONS:
            strength = CONJUNCTIONS[old] * decay[distance]
            if old == 'but' and earlier.strip() != 'but':
                strength *= 0.78
            break
        if any(mark in earlier for mark in '.!?'):
            break
    if not modifier and not contracted and prev not in ('but', 'while', 'yet'):
        strength = 0.0
    if word == 'not' and prev in (
            'may', 'might', 'could', 'would', 'should', 'must'):
        strength *= 0.5
    value = base + gain * strength
    if prev == 'and' and word == 'then':
        value = 0.56
    if word in TRANSLATIONS:
        ordinary, contrast = TRANSLATIONS[word]
        value = contrast if prev in FOREIGN_CONTRASTS else ordinary
    value = PHRASES.get((prev, word), value)
    if prev == 'while' and word.endswith('ing'):
        preservation = word in (
            'maintaining', 'keeping', 'preserving', 'retaining')
        value = 2.2 if preservation else 1.0
    return (doc, (history + (token,))[-4:]), float(value)

programs.haiku:
"""Layer-0 MLP unit 1903 (down_proj, component 1903) as a contrast-continuation detector.

It fires on the word that continues a contrast, most strongly an additive or negating
adverb right after "but" ("but also", "but not", "but rather", "but still", "but only").
Weaker: the same adverbs after "and"/"see" or after an auxiliary ("did not"), the "t" of
"don't"/"doesn't", "as" in "as well as", and mildly negative on "or not" and on
sentence-opening linking adverbs ("Additionally", "Alternatively", "Moreover").
Everything else is predicted as 0.
"""
READS = ()

CONTRAST = {"but", "while", "though", "whereas", "although", "yet", "aber", "но", "а", "但"}
STRONG = {"also", "not", "rather", "only", "still"}
MID = {"then", "now", "no", "with", "instead", "never", "actually", "maybe", "perhaps",
       "neither", "too", "auch", "также", "也", "も", "又", "nicht"}
AUXILIARY = {"do", "does", "did", "don", "doesn", "didn", "can", "won", "wouldn", "couldn"}
CONTRACTION_T = {"'t", "’t"}
LINKERS = {"additionally", "alternatively", "moreover", "likewise", "currently",
           "particularly", "importantly"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if prev in CONTRAST:
        if cur in STRONG:
            return carry, 6.5
        if cur in MID:
            return carry, 2.2
        return carry, 0.2
    if cur in CONTRACTION_T:
        return carry, 1.1
    if prev == "well" and cur == "as":
        return carry, 1.8
    if prev in {"and", "see"} and cur in STRONG:
        return carry, 1.1
    if prev in AUXILIARY and cur == "not":
        return carry, 0.7
    if prev == "or" and cur == "not":
        return carry, -1.3
    if cur in STRONG:
        return carry, 0.2
    if cur in MID:
        return carry, 0.1
    if cur in LINKERS:
        return carry, -0.35
    return carry, 0.0

programs.luna:
"""Approximate the component's weak positive pulse on function words."""
READS = ()

NEGATION_PARTS = {"not", "n't", "n’t", "'t", "’t"}
LINKING_WORDS = {"also", "then", "as", "at", "ever", "now", "yet", "still", "too"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return None, 0.20 if word in NEGATION_PARTS | LINKING_WORDS else 0.0

programs.sol:
"""Respond mainly to written-out one and two, not to digits.
English whole-word one has the largest response, then two. Lower-case one
inside a longer word is weaker; hyphenated endings and capitals have their
own average strengths. Three, four, plural ones, words for a pair, and a few
translations have smaller responses. Everything else is set to zero.
This intentionally leaves out finer lexical and contextual variation.
"""
READS = ()

# Small cardinal numbers in several languages, and common pair expressions.
SMALL_COUNTS = {
    'uno': 0.42, 'один': 0.63,
    'dos': 0.28, 'deux': 0.69, 'zwei': 0.57,
    'два': 0.50, '두': 0.49,
    'couple': 0.35, 'twice': 0.37, 'pair': 0.22,
    'dual': 0.33, 'duo': 0.34,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    spaced = bool(token) and token[0].isspace()
    previous = ''
    if (prefix.position > 0 and
            prefix.document_ids[-2] == prefix.document_ids[-1]):
        previous = prefix.token_strings[-2]

    if lower == 'one':
        if word.isupper():
            value = 1.58 if spaced else 0.43
        elif word[0].isupper() or spaced:
            value = 2.04
        else:
            attached = previous and previous[-1].isalpha()
            value = 0.3 if attached else 2.0
    elif lower == 'two':
        value = 1.16 if spaced else 0.94
        if word[0].isupper():
            value = 1.04 if spaced else 0.90
    elif lower in ('three', 'four'):
        value = {'three': 0.28, 'four': 0.14}[lower]
        if not spaced or word[0].isupper():
            value -= 0.17
    elif lower == 'ones':
        value = 0.44 if spaced else 0.0
    elif lower == '-one':
        value = 1.1
    elif word.startswith(('(', '_', '—')) and lower[1:] == 'one':
        value = 1.5
    elif lower == '-two':
        value = 0.51
    elif lower in SMALL_COUNTS:
        value = SMALL_COUNTS[lower]
    elif any(ch in word for ch in '两兩') and len(word) <= 4:
        value = 1.02 if word in ('两', '兩', '两个') else 0.78
    else:
        value = 0.0
    return None, value

programs.haiku:
"""Counting words "one" and "two", with "one" weaker after "no", "the", "only", "least"
(where it is less of a count: "no one", "the one", "only one", "at least one").

It reads the newest token and the one before it. " one"/"One" (also "-one" in hyphenated
words) gives about 2, lower after those four words; " two"/"Two" and the Chinese 两/兩 give
about 1.1. Weaker bumps for "couple", "three", "four". Everything else is 0.
"""

READS = ()

SMALL = {"couple": 0.3, "ones": 0.4, "three": 0.25, "four": 0.13}
WEAK_BEFORE_ONE = {"no", "the", "only", "least"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip("-")
    if word == "one":
        before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
        value = 1.3 if before in WEAK_BEFORE_ONE else 2.0
    elif word == "two" or token.startswith(("两", "兩")):
        value = 1.1
    else:
        value = SMALL.get(word, 0.0)
    return carry, float(value)

programs.sol:
"""Approximate a word-boundary signal and its chat-format responses.

Negative pulses mark English-looking pieces joined without a space: especially
function words, numbers attached to word labels, and dot-attached sentence
openers. Common suffixes and prefix-like words weaken this response. Chat role
names have separate negative pulses, weaker in tool exchanges and near the
start of a document; framing tags have small offsets. Other tokens mostly get
zero. This leaves small lexical fluctuations and non-English cases unexplained.
"""
import math
from functools import lru_cache

READS = ()
FUNCTION_WORDS = frozenset('''
a an the this that these those all any each every no some other another
my your his her its our their which what whose who whom where when why how
to of in on at by for from with without into onto upon under over after before
between among through as than and or but if so nor yet because while since
although though unless until whether is are was were be been being am do does
did have has had can could may might must shall should will would not
it he she they we you i there here then
'''.split())
PREFIX_LIKE_WORDS = frozenset('''
a an i in at be he her it or on to over under do am no my can
'''.split())
SUFFIXES = frozenset('''
s es ed ing ly er ers est ion ions tion tions ation ations ness ment ments
al ally ic ical ity ities ies ive ous able ible en ent ant ary ory ism ist
ists ize ise ate ates ence ance tive less ful ward wards ology ologies
'''.split())
WORD_ENDINGS = (
    'ing', 'ed', 'ly', 'tion', 'tions', 'ment', 'ments', 'ity', 'ities',
    'ness', 'able', 'ible', 'ive', 'ous', 'ance', 'ence', 'ism', 'ists',
)
PREPOSITIONS = frozenset('''
to of in on at by for from with without into onto upon under over after before
between among through
'''.split())
INDEXED_OBJECTS = frozenset('''
row column layer level step equation problem question case figure table
position line page chapter section example item group part cell block node
edge point vertex degree order
'''.split())
FRAME_OFFSETS = {
    '<tool_call>': -0.01, '</tool_call>': -0.025,
    '<tool_response>': -0.04, '</tool_response>': 0.043,
    '<think>': -0.083, '</think>': 0.025,
}


@lru_cache(maxsize=8192)
def word_kind(token):
    word = token.strip().lower()
    if not token.isascii() or not word.isalpha():
        return word, 'other'
    if word in PREFIX_LIKE_WORDS:
        return word, 'prefix'
    if word in FUNCTION_WORDS:
        return word, 'function'
    ending = any(word.endswith(s) and len(word) > len(s) + 1
                 for s in WORD_ENDINGS)
    if ending or (len(word) > 4 and word.endswith('s')):
        return word, 'ending'
    return word, 'long' if len(word) >= 4 else 'short'


def boundary_value(token, previous):
    word, kind = word_kind(previous)
    if token.startswith('.') and token[1:].isascii() and token[1:].isalpha():
        opening = token[1:]
        if opening[0].isupper():
            long_word = kind in ('long', 'ending')
            if opening.lower() in FUNCTION_WORDS:
                return -0.75 if long_word else -0.2
            return -0.15 if long_word else -0.04
    if token.startswith('-') and token[1:].lower() in FUNCTION_WORDS:
        return -0.32 if kind in ('function', 'ending') else -0.16
    if token.isascii() and token.isdigit() and previous.startswith(' '):
        if word in FUNCTION_WORDS and word not in {'a', 'an', 'i', 'in', 'on', 'at'}:
            return -0.8
        if kind == 'ending' or word in INDEXED_OBJECTS:
            return -0.5
        return -0.18 if kind == 'long' else 0.0
    if not (token.isascii() and token.isalpha()) or kind == 'other':
        return 0.0
    current = token.lower()
    if current in SUFFIXES:
        return 0.0
    spaced = previous.startswith(' ')
    if current == 'the':
        if spaced and (word in PREPOSITIONS or kind == 'function'):
            return -2.5
        if kind == 'function':
            return -0.65
        return -1.0 if kind in ('long', 'ending') else -0.3
    if current in FUNCTION_WORDS:
        if kind == 'function':
            return -0.9 if len(current) >= 4 else -0.5
        return {'ending': -0.35, 'long': -0.1, 'prefix': -0.18}.get(kind, 0.0)
    if token.islower() and kind == 'function':
        return -0.3 if spaced else -0.12
    return 0.0


def chat_value(token, previous, position, tool_context):
    age = math.log1p(position)
    if previous == '<|im_start|>':
        if token == 'assistant':
            if tool_context == 'response':
                return -(1.51 + 0.04 * age) * (1 - math.exp(-position / 6))
            return -1.08 - 1.04 * (1 - math.exp(-(position - 1) / 12))
        if token == 'user':
            if tool_context == 'call':
                return -(0.63 + 0.05 * age) * (1 - math.exp(-position / 8))
            return -0.46 - 0.85 * (1 - math.exp(-(position - 1) / 22))
        if token == 'system':
            return -1.6
    if token == '<|im_start|>':
        return 0.34 if position == 0 else 0.09 - 0.02 * age
    if token == '<|im_end|>':
        if previous == '</tool_call>':
            return 0.15
        if previous == '</tool_response>':
            return 0.076
        return -0.17 if previous.isspace() else -0.019
    return FRAME_OFFSETS.get(token)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, position, tool_context = '', 0, None
    if carry is not None and carry[0] == doc:
        previous, position, tool_context = carry[1], carry[2] + 1, carry[3]
    token = prefix.token_strings[-1]
    value = chat_value(token, previous, position, tool_context)
    if value is None:
        value = boundary_value(token, previous)
        if position == 0 and token.isascii() and token.isalpha():
            word = token.lower()
            if token == 'assistant':
                value = -1.24
            elif word == 'the':
                value = -1.61 if token.islower() else -0.18
            elif word in FUNCTION_WORDS and len(word) > 1:
                value = -0.55 if token.islower() else -0.2
    if previous == '<|im_start|>':
        tool_context = None
    if token in ('<tool_call>', '</tool_call>'):
        tool_context = 'call'
    if token in ('<tool_response>', '</tool_response>'):
        tool_context = 'response'
    return (doc, token, position, tool_context), float(value)

programs.luna:
"""Mark a speaker name when it immediately follows the chat-start marker."""
READS = ()

ROLE_ACTIVATION = {
    "assistant": -1.9,
    "user": -0.85,
    "system": -0.85,
    "developer": -0.85,
}

def step(carry, prefix, upstream):
    value = 0.0
    if len(prefix.token_ids) >= 2:
        previous = prefix.token_strings[-2]
        current = prefix.token_strings[-1]
        if previous == "<|im_start|>":
            value = ROLE_ACTIVATION.get(current, 0.0)
    return None, float(value)

programs.sol:
"""Estimate a response to expressions that count or introduce individual things.
Chinese 个/個 counter phrases are strongest, with smaller predictions when
content follows the counter within the same token. 'Each', other counter
words, and small written cardinal numbers also receive negative predictions.
For English 'a/an', preceding grammatical word classes set the magnitude:
possession/creation verbs are strongest; ordinary copulas are weak, except
for 'there is a'. Selected prepositions/actions lie between these cases.
This is a lexical/grammar approximation, not a complete semantic parser.
Only two preceding tokens are retained, resetting at document boundaries.
Unrecognized tokens predict zero. Magnitudes are rounded training estimates.
"""
READS = ()

COPULA = set('am is are was were be been being become becomes became'.split())
POSSESSION = set('have has had having'.split())
CREATION = set('create provide develop offer generate adopt establish introduce '
               'receive issue obtain produce propose share upload'.split())
ACTION = set('make get give find take use form include need want require build '
             'construct contain add show maintain choose prepare publish '
             'write present'.split())
PLACE = set('in on at from with into over through within during out via'.split())
RELATION = set('of to by about'.split())
LINK = set('as like or but than if when that which such where while because since '
           'so just only even quite then now actually also'.split())
CARDINAL = set('two three four five six seven eight nine ten'.split())
DEFINITE = set('the these those any every no first last next'.split())
IRREGULAR = {'made': 'make', 'given': 'give', 'gave': 'give', 'got': 'get',
             'found': 'find', 'took': 'take', 'taken': 'take', 'built': 'build',
             'wrote': 'write', 'written': 'write'}
# Other counter/distributive words, with rounded training magnitudes.
COUNTERS = {'개': -2.6, ' 개': -3.1, 'つ': -0.75, '一つ': -0.8, 'つの': -2.0,
            '各': -0.92, '条': -0.64, '座': -0.53, '颗': -0.95}
DISTRIBUTIVE = {'каждый': -0.84, 'каждого': -0.84, 'каждой': -0.5,
                'cada': -0.32, 'cái': -0.94}
GERMAN_ARTICLE = {'einen': -0.46, 'einer': -0.38, 'einem': -0.29}


def verb_base(word):
    if word in IRREGULAR:
        return IRREGULAR[word]
    roots = CREATION | ACTION
    for ending in ('', 'ing', 'ed', 'es', 's'):
        stem = word[:-len(ending)] if ending and word.endswith(ending) else word
        for candidate in (stem, stem + 'e', stem[:-1]):
            if candidate in roots:
                return candidate
    return word


def indefinite(prev, prev2, word):
    offset = 0.17
    if prev in COPULA | {"'s", '’s'}:
        value = -0.7 if prev2 == 'there' else -0.25 if prev2 == 'here' else 0.04
        offset = 0.17 if prev2 in {'there', 'here'} else 0.06
    elif prev in POSSESSION or verb_base(prev) in CREATION:
        value = -0.97
    elif verb_base(prev) in ACTION or prev in PLACE:
        value = -0.72 if prev in {'with', 'into', 'over', 'through'} else -0.63
    elif prev in RELATION or prev == 'for':
        value = -0.54 if prev == 'for' else -0.44
    elif prev in {'not', 'what'}:
        value, offset = 0.28, 0.08
    elif prev in LINK or prev == 'and':
        value, offset = (-0.07 if prev == 'and' else 0.05), 0.12
    elif not prev or not any(c.isalpha() for c in prev):
        value, offset = 0.1, 0.1
    else:
        value, offset = -0.25, 0.13
    return value - (offset if word == 'an' else 0.0)


def chinese_counter(token):
    traditional = '個' in token
    s = token.replace('個', '个').replace('這', '这')
    if not s.endswith('个'):
        return -1.2 if len(s) > 2 else -0.75
    if s == '个':
        return -5.7 if traditional else -5.3
    if s in {'了个', '有个'}:
        return -5.6
    if s in {'一个', '了一个'}:
        return -5.05 if traditional else -4.65
    if s in {'这个', '那个'}:
        return (-5.1 if s == '这个' else -4.2) if traditional else -4.6
    return -3.05 if s.endswith('整个') else -3.65


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, prev2 = '', ''
    else:
        _, prev, prev2 = carry
    word = token.strip().lower()
    value = COUNTERS.get(token,
                         DISTRIBUTIVE.get(word, GERMAN_ARTICLE.get(word, 0.0)))
    if '个' in token or '個' in token:
        value = chinese_counter(token)
    elif token in {' a', ' an'}:
