                -(2.1 if spaced else 3.0))
        if n == 2:
            return -2.5
        if n == 3:
            return -3.15 if spaced else -2.75
        return -4.0 if n == 4 else -3.1
    if mark.startswith(('!!', '??')):
        return -1.4
    if mark in ('.?', '.!', ':?'):
        return -0.6
    if mark in ('(!', '?.', '?,', '?-', '?:'):
        return -0.2
    if mark == '//!':
        return -0.38 if newline else -0.75
    if mark == '!==':
        return -0.15 if spaced else -0.5
    if n >= 2 and len(set(mark)) == 1:
        c = mark[0]
