        if c == '~':
            return -0.8 if n <= 4 else -0.4 if n <= 8 else -0.08
        if c == '^':
            return -0.38 if n == 2 else -0.56
        if c in ';,':
            return -0.35 if n == 2 else -0.8
        if c == '%':
            return -0.45 if n == 2 else -0.8
        if c == '+' and 3 <= n <= 8:
            return -0.5 if n == 3 else -0.75
        if c == '$' and 3 <= n <= 4:
            return -0.6 if n == 3 else -0.32
        if c == '/' and 3 <= n <= 4:
            return -0.12 if spaced else -0.28
        if c == '*' and 3 <= n <= 6:
            return -0.5 if n >= 5 else -0.2
        if c == '=' and 3 <= n <= 14:
            return -0.15
        if c == '.' and n == 2 and not spaced:
            return -0.12 if newline else -0.06
        if c == '.' and 4 <= n <= 9 and not spaced:
            return -0.12
        if c == '·':
