"""Approximate the component's positive evidence/exemplification responses.

Recognize proof, examples, signs, reasons, and related support vocabulary.
Immediately preceding determiners and emphatic adjectives change the score;
'for example/instance' is suppressed. Most capitalized or attached forms are
weaker. The response extends to a following of/for/to/that, with a few phrase
adjustments. Reset at document boundaries and omit small background responses.
"""
READS = ()

STRENGTH = {
    'evidence': 2.0, 'proof': 1.5, 'proofs': 0.8,
    'example': 1.25, 'examples': 1.6, 'reminder': 1.4,
    'sign': 0.95, 'signs': 1.6, 'indicator': 1.0, 'indication': 1.1,
    'reason': 0.85, 'reasons': 0.85, 'explanation': 0.9,
    'instance': 0.55, 'instances': 0.65, 'embodiment': 0.7,
    'symptom': 0.7, 'symptoms': 0.7, 'illustration': 0.6,
    'reference': 0.5, 'references': 0.65, 'source': 0.3,
    'sources': 0.45, 'testimony': 0.5, 'testament': 0.85,
    'hint': 0.65, 'clear': 0.58, 'obvious': 0.58, 'evident': 0.65,
}
DEFINITE = {'the', 'this', 'that', 'these', 'those', 'its', 'your', 'our'}
INDEFINITE = {'a', 'an', 'any', 'no', 'some', 'few', 'another', 'one'}
EMPHATIC = {'good', 'excellent', 'concrete', 'direct', 'indirect',
            'strong', 'compelling', 'scientific', 'supporting', 'visual'}
LINK = {'of': 1.0, 'for': 0.55, 'to': 0.3, 'that': 0.55}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().strip('/_.-([]').lower()
    doc = prefix.document_ids[-1]
    previous, strength = ('', 0.0) if carry is None or carry[0] != doc else carry[1:]
    value = STRENGTH.get(word, 0.0)
    if value:
        if previous in DEFINITE:
            value *= 0.7
        elif previous in INDEFINITE:
            value *= 1.3
        elif previous in EMPHATIC:
            value *= 1.65
        if word == 'example' and previous in DEFINITE:
            value = 0.45
        if word in {'example', 'instance'} and previous == 'for':
            value = -0.1
        elif raw.strip()[:1].isupper() or not raw.startswith(' '):
            value *= 0.65
    elif word in LINK and previous in STRENGTH:
        value = LINK[word] * max(0.0, strength)
        if word == 'of' and previous in {'example', 'examples'}:
            value += 0.4
        elif word == 'of' and previous == 'embodiment':
            value *= 0.6
        elif word == 'for' and previous == 'evidence':
            value = 1.8
        elif word == 'to' and previous == 'testament':
            value = 1.05
    return (doc, word, value), float(value)

programs.haiku:
"""Concept program v1: word classes and code-name patterns, each with its mean activation."""
import re

READS = ()

INTENSIFIERS = {"so", "very", "really", "quite", "rather", "pretty", "completely", "entirely", "extremely", "totally", "truly", "fairly"}
NUMBER_WORDS = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "first", "second", "third", "hundred", "thousand", "million"}
CODE_NAME = re.compile(r"<[A-Z]\w*|\.[A-Za-z]*[A-Z]\w*|_[A-Z]\w*|\w*(Key|Item|Entry|Value|Handler|Update|Stack)\w*")
PATH = re.compile(r"/+|:/+|\.(com|org|net)|-[a-z]+|_modules|api")
CJK = re.compile(r"[぀-ヿ㐀-鿿가-힯]")

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    if s in INTENSIFIERS:
        value = 0.03
    elif s in NUMBER_WORDS:
        value = 0.007
    elif CODE_NAME.fullmatch(s):
        value = -0.02
    elif PATH.fullmatch(s):
        value = 0.005
    elif CJK.search(s):
        value = 0.003
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Recognize definite articles, chiefly English 'the'.

Case and document position govern the large English response. Common
function-word frames adjust lowercase 'the': linking verbs suppress it,
while 'of', 'for', 'with' and 'by' strengthen it. Other European definite
articles, including fused preposition+article forms, respond more weakly.
"""
import re

READS = ()
ENGLISH = re.compile(r'^[\W_]*(the|The|THE)$')

# Baseline response for common grammatical frames before lowercase 'the'.
FRAMES = (
    (-0.13, 'is be being was were are been become becomes became remain remains'),
    (0.40, "'s ’s not both just also represent represents"),
    (1.05, 'in as into over between all during within before after along near'),
    (1.70, 'of for that with by using'),
    (1.50, 'to on at and but about where whether if so since or which , ; : .'),
)
FRAMES = tuple((value, frozenset(words.split())) for value, words in FRAMES)

# French, Spanish, German, Italian and Dutch articles and contractions.
ARTICLES = {
    'la': 1.22, 'el': 1.14, 'los': 1.09, 'las': 1.09,
    'die': 1.17, 'das': 1.00, 'der': 0.73, 'den': 0.55, 'dem': 0.66,
    'le': 0.76, 'les': 0.73, 'des': 0.36, 'du': 0.45, 'del': 0.63,
    'il': 0.58, 'lo': 0.41, 'gli': 0.60, 'della': 0.84,
    'nella': 1.00, 'nel': 0.75, 'delle': 0.65, 'het': 0.79,
    'im': 0.33, 'vom': 0.77, 'zur': 0.53, 'au': 0.42,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    token = prefix.token_strings[-1]
    match = ENGLISH.fullmatch(token)
    value = 0.0
    if match:
        word = match[1]
        if word == 'The':
            bare = token == 'The'
            value = (3.08 + 2.68 / (1 + position / 2) ** 0.5 if bare else
                     2.84 + 1.86 / (1 + position / 8) ** 0.75)
            if position == 0:
                value = 9.06 if bare else 6.48
        elif word == 'THE':
            value = 2.30
        elif token == ' the':
            value = 1.22
            for baseline, words in FRAMES:
                if previous.strip().lower() in words:
                    value = baseline
                    break
            value += 0.47 / (1 + position / 4) ** 0.25
            if position == 0:
                value = 2.66
        else:
            value = 3.46 if position == 0 else 2.15
            if token == 'the' and previous and previous[-1].isalpha():
                value -= 0.80
    else:
        word = token.strip()
        if token.startswith(' '):
            value = ARTICLES.get(word, 0.0)
        if word.istitle() and word.lower() in ARTICLES:
            value = ARTICLES[word.lower()] + 0.25
            if not token.startswith(' '):
                value += 0.20
    return (doc, position + 1, token), float(value)

programs.haiku:
"""Definite articles: fires on "the" and its counterparts in other languages.
Strongest on a capitalised "The" that opens a document; strong on sentence-initial
"The"; mid-sentence "the" is moderate, weaker after place/time prepositions
("in the", "within the"), and switched off after a form of "be" ("is the")."""
READS = ()

COPULA = {"is", "was", "are", "were", "be", "been", "being", "am", "'s", "not"}
WEAK_BEFORE = {"in", "into", "within", "over", "during", "between", "after", "before",
               "as", "than", "along", "up", "out", "throughout", "across", "under"}
FOREIGN = {"la", "le", "les", "el", "los", "las", "die", "der", "das", "dem", "den",
           "il", "gli", "della", "delle", "del", "nella", "nel"}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    bare = word.strip()
    spaced = word.startswith(" ")
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    first = len(prefix) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    if bare == "The":
        value = 9.0 if first else (3.1 if spaced else 3.4)
    elif bare == "THE":
        value = 2.3
    elif bare == "the":
        if first:
            value = 2.7
        elif not spaced:
            value = 2.0
        elif prev in COPULA:
            value = 0.0
        elif prev in WEAK_BEFORE:
            value = 1.25
        else:
            value = 1.8
    elif (spaced or bare[:1].isupper()) and bare.lower() in FOREIGN:
        value = 1.2
    else:
        value = 0.0
    return None, value

programs.luna:
"""Estimate this component with a small cue for definite articles.

It gives the strongest positive response to English “the,” especially when
capitalized, and a smaller response to common definite articles in other
European languages. Other words receive zero.
"""

READS = ()

ARTICLES = frozenset({
    "die", "das", "der", "den", "dem", "des",
    "la", "el", "los", "las",
    "le", "les", "du", "il", "lo", "gli",
    "del", "della", "delle", "dello",
})


def _word(token):
    word = token.strip()
    while word and not word[0].isalnum():
        word = word[1:]
    return word


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = _word(token)
    if not word:
        return None, 0.0

    if word.lower() == "the":
        if word.isupper():
            value = 2.5
        elif word[0].isupper():
            value = 3.2 if token[:1].isspace() else 3.8
        else:
            value = 1.5 if token[:1].isspace() else 2.0
        return None, value

    if word.lower() in ARTICLES:
        value = 1.4 if word[0].isupper() else 1.0
        return None, value

    return None, 0.0

programs.sol:
"""Lexical responses to cities and urban administration, across several languages.

English city/urban words and 市 produce the largest negative contributions.
Municipalities, towns, provinces, markets, and universities give smaller ones.
A city morpheme inside a longer CJK token is diluted by its other characters;
market compounds use a weaker response. Capitalization and word boundaries
adjust a few strengths. A one-token memory recognizes familiar names ending
in City and the phrase 'city of'; it resets between documents. Other tokens
receive zero, leaving the component's smaller unrelated lexical effects out.
"""
READS = ()

# Translations of 'city' and 'town', with their different response strengths.
CITY_WORDS = {
    'ville': -0.85,
    'stadt': -1.75,
    'città': -1.7,
    'ciudad': -1.45,
    'cidade': -1.05,
    'город': -2.25,
    'города': -1.35,
    'городе': -1.5,
    'büyükşehir': -1.8,
    'município': -1.5,
    'thị': -1.4,
    'phố': -1.2,
    'kota': -0.85,
    'nyc': -1.55,
}
TOWN_WORDS = {'town', 'towns', 'downtown', 'borough', 'suburbs'}
PROVINCE_WORDS = {'province', 'provinces', 'provincial', 'provinc', 'provincia'}
CITY_NAME_ENDINGS = {
    'York', 'Kansas', 'Oklahoma', 'Mexico', 'Manchester', 'Jersey', 'Lake',
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.casefold()
    boundary = raw[:1].isspace()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0

    if word.lstrip('-_.') == 'city':
        value = -3.85 if boundary else -2.95
        if token == 'City' and boundary:
            value = -4.2
            if previous.casefold() in {'the', 'a'}:
                value = -4.6
        # These established names weaken the standalone City response.
        if token == 'City' and previous in CITY_NAME_ENDINGS:
            value = -2.9
    elif word == 'cities':
        value = -3.15 if boundary or token[:1].isupper() else -2.0
    elif word == 'urban':
        value = -2.95 if token[:1].isupper() else -1.9
        if boundary:
            value = -3.65
    elif word == 'municipal':
        value = -2.5
    elif word in {'municipality', 'municipalities', 'municip', 'unicip'}:
        value = -1.65
    elif word in CITY_WORDS and boundary:
        value = CITY_WORDS[word]
    elif token == '시':
        value = -3.0 if raw[:1].isspace() else -2.25
    elif '市' in token:
        if '市场' in token:
            value = -1.5 if len(token) <= 3 else -0.9
        elif '市場' in token or token in {'超市', '集市'}:
            value = -1.05
        elif token in {'股市', '市值', '牛市', '楼市'}:
            value = -2.0
        elif '城市' in token or '都市' in token:
            value = -9.6 / len(token)
        elif token.startswith('市') and len(token) > 1:
            value = -4.1
        else:
            value = -8.7 / len(token) ** 0.65
    elif token in {'城', '县城', '城区', '京城', '城镇'}:
        value = -1.45
    elif token == '省' or (token.endswith('省') and len(token) == 3):
        value = -1.3
    elif token in {'县', '縣', '镇', '町', '県'}:
        value = -0.85
    elif word in TOWN_WORDS:
        value = -0.9
        if word == 'town' and not boundary and token.islower():
            value = -0.3
    elif word == 'hometown':
        value = -0.45
    elif word in PROVINCE_WORDS:
        value = -0.75
    elif word.lstrip('-') in {'market', 'markets'}:
        value = -1.1
    elif word in {'university', 'universities', 'universe'}:
        value = -0.6
    elif word in {'metropolitan', 'suburban'}:
        value = -0.85
    elif word == 'mayor':
        value = -1.6 if token[:1].isupper() else -0.9
    elif word == 'commercial':
        value = -0.55
    elif word == 'commercially':
        value = -1.2
    elif token == '州':
        value = -0.7

    if word == 'of':
        if previous.casefold() in {'city', 'cities'}:
            value = -1.05
        elif previous.casefold() in {'town', 'province', 'municipality'}:
            value = -0.45

    return (doc, token), value

programs.luna:
"""City labels are the strongest clue; related place and civic words get weaker values."""

READS = ()

_CITY_WORDS = {"city"}
_CIVIC_WORDS = {
    "town", "towns", "suburb", "suburbs", "mayor", "metro",
    "commercial", "ville", "ciudad", "cidade", "universe", "mercado",
    "商业", "商業", "机关",
}
_ADMIN_ENDINGS = ("縣", "县", "镇", "鎮", "省", "町", "県")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    word = word.strip(" \t\r\n.,;:!?()[]{}'\"—–-")

    if word in _CITY_WORDS:
        return None, -3.7
    if word == "cities":
        return None, -3.3
    if word in {"market", "markets"}:
        return None, -1.05
    if any(term in word for term in ("市场", "市場", "超市")):
        return None, -1.05
    if word == "市":
        return None, -8.8
    if word == "시":
        return None, -2.5
    if "市" in word:
        return None, -4.5
    if "城" in word:
        return None, -1.8
    if any(word.endswith(mark) for mark in _ADMIN_ENDINGS):
        return None, -0.9
    if word == "urban":
        return None, -3.2
    if word == "urb":
        return None, -1.5
    if word in {"città", "города"}:
        return None, -1.5
    if word == "город":
        return None, -1.2
    if word == "stadt":
        return None, -1.5
    if word.startswith("municip") or word == "mayor":
        return None, -1.5
    if word.startswith(("provinc", "metropol")):
        return None, -0.8
    if word.startswith("univers") and word != "universe":
        return None, -0.45
    if word in {"marketplace", "marketplaces"}:
        return None, -0.35
    if word.startswith("рын"):
        return None, -1.5
    if word == "mars":
        return None, -0.6
    same_document = (
        len(prefix.document_ids) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    if word == "of" and same_document:
        previous = prefix.token_strings[-2].strip().casefold()
        if previous in {"city", "town", "municipality"}:
            return None, -0.9
    if word in _CIVIC_WORDS:
        if word == "ville":
            return None, -0.4
        if word in {"commercial", "mercado", "商业", "商業", "机关"}:
            return None, -0.55
        return None, -0.8
    return None, 0.0

"""Approximate the component with a sparse cue for source-code closers.

Any token containing `}` gets a small positive score. Commas and backslashes
attached to it lower the score, as do closing parentheses and semicolons;
all other tokens get zero. This deliberately leaves other responses out.
"""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "}" in token:
        if "," in token or "\\" in token:
            return None, 0.18
        if ")" in token or ";" in token:
            return None, 0.255
        return None, 0.31
    return None, 0.0
